NAME = 'ACV: A Conservative Version'
BOOK = 'John'

CHAPTERS = {
    1: {
        1: 'V začetku je bila Beseda, in Beseda je bila pri Bogu, in Bog je bila Beseda.',
        2: 'Ta je bila v začetku pri Bogu.',
        3: 'Vse je po njej postalo, in brez nje ni nič postalo, kar je postalo.',
        4: 'V njej je bilo življenje, in življenje je bilo luč ljudem.',
        5: 'In luč sveti v temi, in tema se je ni polastila.',
        6: 'Nastopil je človek, poslan od Boga, ki mu je bilo ime Janez.',
        7: 'Ta je prišel na pričevanje, da priča za Luč, da bi vsi verovali po njem.',
        8: 'On ni bil Luč, ali prišel je, da priča za Luč.',
        9: 'Prava Luč, ki razsvetljuje vsakega človeka, je že prihajala na svet.',
        10: 'Na svetu je bil, in svet je postal po njem, a svet ga ni spoznal.',
        11: 'V svojo last je prišel, in svojci ga niso sprejeli.',
        12: 'A katerikoli so ga sprejeli, jim je dal oblast, da postanejo otroci Božji, njim, ki verujejo v ime njegovo,',
        13: 'ki se niso rodili iz krvi, ne iz volje mesa, ne iz volje moža, marveč iz Boga.',
        14: 'In Beseda je postala meso in je prebivala med nami (in videli smo slavo njeno, slavo kakor Edinorojenega od Očeta), polna milosti in resnice.',
        15: 'Janez pričuje zanj in kliče, govoreč: Ta je bil, ki sem rekel o njem: Ta, ki prihaja za menoj, je bil tu pred menoj; kajti bil je prej nego jaz.',
        16: 'In od polnosti njegove smo mi vsi prejeli, in to milost za milost.',
        17: 'Kajti postava je bila dana po Mojzesu, milost in resnica je postala po Jezusu Kristusu.',
        18: 'Boga ni nikoli nihče videl; edinorojeni Sin, ki je v naročju Očetovem, on ga je oznanil.',
        19: 'In to je pričevanje Janezovo, ko so poslali Judje iz Jeruzalema duhovnike in levite, naj ga vprašajo: Kdo si ti?',
        20: 'In je priznal in ni utajil; in prizna: Jaz nisem Kristus.',
        21: 'In vprašajo ga: Kaj si torej? Elija si ti? In reče: Nisem. Prorok si ti? In odgovori: Ne.',
        22: 'Reko mu torej: Kdo si? da odgovor damo tem, ki so nas poslali. Kaj praviš sam o sebi?',
        23: 'Reče: Jaz sem „glas vpijočega v puščavi: Poravnajte pot Gospodov“, kakor je povedal Izaija prorok.',
        24: 'Poslanci pa so bili izmed farizejev.',
        25: 'In ga vprašajo in mu reko: Zakaj torej krščuješ, če nisi Kristus, ne Elija, ne prorok?',
        26: 'Odgovori jim Janez, rekoč: Jaz krščujem z vodo; sredi med vami pa stoji, ki ga vi ne poznate,',
        27: 'on, ki gre za menoj, ki mu jaz nisem vreden odvezati jermena na obuvalu njegovem.',
        28: 'To se je zgodilo v Betaniji onkraj Jordana, kjer je Janez krščeval.',
        29: 'Drugi dan ugleda Janez Jezusa, da gre k njemu, ter reče: Glej, Jagnje Božje, ki odjemlje greh sveta!',
        30: 'Ta je, ki sem rekel o njem: Za menoj prihaja mož, ki je bil tu pred menoj; kajti bil je prej nego jaz.',
        31: 'In jaz ga nisem poznal; ali da se razodene Izraelu, zato sem prišel krščevat z vodo.',
        32: 'In pričuje Janez, rekoč: Videl sem Duha, da prihaja ko golob z neba, in je ostal na njem.',
        33: 'In jaz ga nisem poznal; ali ta, ki me je poslal krščevat z vodo, mi je rekel: Na kogar boš videl, da pride Duh in ostane na njem, ta je, ki krščuje s svetim Duhom.',
        34: 'In jaz sem ga videl in izpričal, da je ta Sin Božji.',
        35: 'Drugi dan je stal zopet Janez in dva izmed učencev njegovih;',
        36: 'in pogleda Jezusa, ki gre mimo, in reče: Glej, Jagnje Božje!',
        37: 'In slišala sta ga oba učenca, ko je govoril, ter odideta za Jezusom.',
        38: 'Jezus se pa obrne in ko ju ugleda, da gresta za njim, jima reče: Kaj iščeta? Ona pa mu rečeta: Rabi (kar se pravi, če raztolmačiš: Učenik), kje stanuješ?',
        39: 'Veli jima: Pridita in poglejta! Gresta torej in vidita, kje stanuje, in ostaneta pri njem tisti dan. Bilo je okoli desete ure.',
        40: 'Eden teh dveh, ki sta to slišala od Janeza in sta šla za njim, je bil Andrej, brat Simona Petra.',
        41: 'Ta najde najprej brata svojega Simona in mu reče: Našli smo Mesija (kar se tolmači: Kristus).',
        42: 'Njega pripelje k Jezusu. Jezus pogleda nanj in reče: Ti si Simon, sin Jonov; ti se boš imenoval Kefa (kar se tolmači: Peter.',
        43: 'Drugi dan je hotel Jezus oditi v Galilejo; in najde Filipa in mu reče: Pojdi za menoj!',
        44: 'Filip pa je bil iz Betsaide, mesta Andrejevega in Petrovega.',
        45: 'Filip najde Natanaela in mu reče: Našli smo ga, ki je pisal o njem Mojzes v zakonu in proroki, Jezusa iz Nazareta, sina Jožefovega.',
        46: 'Pa mu Natanael reče: More li iz Nazareta priti kaj dobrega? Veli mu Filip: Pridi in poglej!',
        47: 'Jezus vidi Natanaela, da gre k njemu, ter reče o njem: Glej, pravi Izraelec, v katerem ni zvijače!',
        48: 'Reče mu Natanael: Odkod me poznaš? Jezus odgovori in mu reče: Preden te je Filip poklical, ko si bil pod smokvo, sem te videl.',
        49: 'Natanael mu odgovori: Rabi, ti si Sin Božji, ti si kralj Izraelov.',
        50: 'Jezus odgovori in mu veli: Ker sem ti dejal, da sem te videl pod smokvo, veruješ? Večje reči boš videl nego to.',
        51: 'In mu reče: Resnično, resnično vam pravim: Videli boste nebesa odprta in angele Božje stopati gori in doli do Sina človekovega.',
    },
    2: {
        1: 'In tretji dan je bila ženitnina v Kani Galilejski, in mati Jezusova je bila tam.',
        2: 'Povabili pa so tudi Jezusa in učence njegove na ženitnino.',
        3: 'In ko zmanjka vina, reče mati Jezusova njemu: Vina nimajo.',
        4: 'In reče ji Jezus: Kaj imaš z menoj, žena? Moja ura še ni prišla.',
        5: 'Mati njegova reče služabnikom: Karkoli vam poreče, storite.',
        6: 'Bilo je pa tam šest kamenenih vrčev, postavljenih po šegi očiščevanja judovskega, ki so držali po dve ali tri mere.',
        7: 'Veli jim Jezus: Napolnite vrče z vodo. In napolnijo jih do vrha.',
        8: 'In jim veli: Zajmite sedaj, in nesite starejšini. Ter neso.',
        9: 'Ko pa okusi starejšina vodo, ki je postala vino (ni pa vedel, odkod je, a služabniki so vedeli, ki so bili zajemali vodo), pokliče starejšina ženina',
        10: 'in mu reče: Vsak človek daje najprej dobro vino, in ko se napijejo, tedaj tisto, ki je slabše: a ti si prihranil dobro vino do sedaj.',
        11: 'Ta začetek čudežev je storil Jezus v Kani Galilejski in je razodel slavo svojo; in verovali so vanj učenci njegovi.',
        12: 'Potem gre doli v Kafarnavm, on in mati njegova in bratje in učenci njegovi, in tu ostanejo ne veliko dni.',
        13: 'In bila je blizu Velika noč Judov, in Jezus se napoti v Jeruzalem.',
        14: 'In najde v templju prodajalce volov in ovac in golobov ter menjalce, sedeče pri svojih mizah.',
        15: 'In splete bič iz vrvic in izžene vse iz templja, tudi ovce in vole; in menjalcem raztrese denar in prevrne mize,',
        16: 'in tem, ki so prodajali golobe, veli: Odnesite to odtod; ne delajte iz hiše Očeta mojega hiše trgovske.',
        17: 'Spomnijo pa se učenci njegovi, da je pisano: „Gorečnost za hišo tvojo me razjeda“.',
        18: 'Judje torej odgovore in mu reko: Kakšno znamenje nam pokažeš, ker delaš to?',
        19: 'Jezus odgovori in jim reče: Poderite to svetišče, in v treh dneh ga postavim.',
        20: 'Pa mu reko Judje: Šestinštirideset let so zidali to svetišče, in ti ga postaviš v treh dneh?',
        21: 'Ali on je govoril o svetišču telesa svojega.',
        22: 'Ko je bil torej vstal iz mrtvih, so se spomnili učenci njegovi, da jim je to pravil; in verovali so pismu in besedi, ki jo je bil Jezus povedal.',
        23: 'Ko pa je bil v Jeruzalemu o Veliki noči, ob prazniku, jih je mnogo sprejelo vero v ime njegovo, ko so videli znamenja njegova, ki jih je delal.',
        24: 'On pa, Jezus, se jim ni zaupal, ker jih je vse poznal',
        25: 'in ker mu ni bilo treba, da bi kdo pričal o človeku: sam je namreč vedel, kaj je v človeku.',
    },
    3: {
        1: 'Bil pa je človek med farizeji, Nikodem po imenu, poglavar Judov.',
        2: 'Ta pride k Jezusu po noči in mu reče: Rabi! vemo, da si od Boga prišel kot učenik; zakaj nihče ne more delati teh znamenj, ki jih ti delaš, če Bog ni ž njim.',
        3: 'Jezus odgovori in mu reče: Resnično, resnično ti pravim: Če se kdo na novo ne rodi, ne more videti kraljestva Božjega.',
        4: 'Reče mu Nikodem: Kako se more človek roditi, ko je star? Ali more drugič iti v telo matere svoje in se roditi?',
        5: 'Jezus odgovori: Resnično, resnično ti pravim: Če se kdo ne rodi iz vode in Duha, ne more priti v kraljestvo Božje.',
        6: 'Kar se je rodilo iz mesa, je meso, in kar se je rodilo iz Duha, je duh.',
        7: 'Ne čudi se, da sem ti rekel: Treba se vam je na novo roditi.',
        8: 'Veter veje, kjer hoče, in glas njegov slišiš, pa ne veš, odkod prihaja in kam gre: tako je z vsakim, ki je rojen iz Duha.',
        9: 'Nikodem odgovori in mu reče: Kako se more to zgoditi?',
        10: 'Jezus pa odgovori in mu reče: Ti si učenik Izraelov, in tega ne veš?',
        11: 'Resnično, resnično ti pravim: Kar vemo, govorimo, in kar smo videli, pričamo, ali pričevanja našega ne sprejemate.',
        12: 'Če vam pravim pozemeljske reči, in ne verujete, kako boste verovali, če vam bom pravil nebeške?',
        13: 'In nihče ni stopil v nebesa, razen kdor je prišel iz nebes, Sin človekov, ki je v nebesih.',
        14: 'In kakor je Mojzes povišal kačo v puščavi, tako mora biti povišan Sin človekov,',
        15: 'da se ne pogubi, kdorkoli veruje vanj, temuč da ima večno življenje.',
        16: 'Kajti tako je Bog ljubil svet, da je dal Sina svojega edinorojenega, da se ne pogubi, kdorkoli veruje vanj, temuč da ima večno življenje.',
        17: 'Bog namreč ni poslal Sina svojega na svet, da bi svet sodil, marveč da se svet zveliča po njem.',
        18: 'Kdor veruje vanj, ne bo sojen; kdor ne veruje, je že obsojen, ker ni veroval v ime edinorojenega Sina Božjega.',
        19: 'Sodba je pa to, da je luč prišla na svet, ali ljudje so bolj ljubili temo nego luč: zakaj njih dela so bila hudobna.',
        20: 'Vsak namreč, kdor dela hudobno, sovraži luč in ne hodi k luči, da se ne karajo dela njegova;',
        21: 'kdor pa dela resnico, hodi k luči, da se razodenejo dela njegova, ker so v Bogu storjena.',
        22: 'Potem pride Jezus in učenci njegovi v Judejsko deželo, in tu prebiva ž njimi in krščuje.',
        23: 'Krščeval je pa tudi Janez v Enonu blizu Salima, ker je bilo tam mnogo vode, in ljudje so prihajali in se dali krstiti.',
        24: 'Janez namreč še ni bil vržen v ječo.',
        25: 'Nastane torej prepir med učenci Janezovimi in nekim Judom o očiščevanju.',
        26: 'In pridejo k Janezu in mu reko: Rabi! ta, ki je bil s teboj onkraj Jordana, ki si zanj ti pričal, glej, ta krščuje in vsi gredo k njemu.',
        27: 'Janez odgovori in reče: Človek ne more ničesar vzeti, če mu ni dano iz nebes.',
        28: 'Vi sami ste mi priče, da sem rekel: Jaz nisem Kristus, ali poslan sem pred njim.',
        29: 'Kdor ima nevesto, je ženin; prijatelj pa ženinov, ki stoji in ga posluša, se srčno veseli glasu ženinovega. To veselje moje je torej dopolnjeno.',
        30: 'On mora rasti, jaz pa se manjšati.',
        31: 'Kdor prihaja od zgoraj, ta je nad vsemi. Kdor je iz zemlje, je pozemski in govori zemske reči. Kdor je prišel iz nebes, ta je nad vsemi,',
        32: 'in kar je videl in slišal, to priča: a njegovega pričevanja nihče ne sprejema.',
        33: 'Kdor je sprejel njegovo pričevanje, je potrdil, da je Bog resničen.',
        34: 'Kajti ta, ki ga je poslal Bog, govori besede Božje: zakaj njemu Bog ne daje Duha na mero.',
        35: 'Oče ljubi sina, in vse mu je dal v roko.',
        36: 'Kdor veruje v Sina, ima večno življenje; a kdor je neveren Sinu, ne bo videl življenja, ampak jeza Božja ostane na njem.',
    },
    4: {
        1: 'Ko torej zve Gospod, da so farizeji slišali, da Jezus dobiva in krščuje več učencev nego Janez',
        2: '(dasi Jezus sam ni krščeval, marveč učenci njegovi),',
        3: 'zapusti Judejo in gre zopet v Galilejo.',
        4: 'Moral je pa iti skozi Samarijo.',
        5: 'Pride torej do samarijskega mesta, ki se imenuje Sihar, blizu zemljišča, ki ga je dal Jakob Jožefu, sinu svojemu.',
        6: 'Tam pa je bil studenec Jakobov. Jezus torej, truden od pota, kakor je bil, sede k studencu. Bilo je okoli šeste ure.',
        7: 'Kar pride žena iz Samarije zajemat vode. Veli ji Jezus: Daj mi piti.',
        8: 'Učenci njegovi so namreč odšli v mesto, da kupijo živeža.',
        9: 'Pa mu žena Samarijanka reče: Kako prosiš ti, ki si Jud, mene, ki sem žena Samarijanka, naj ti dam piti? (Judje namreč se ne pečajo s Samarijani.)',
        10: 'Jezus odgovori in ji reče: Ko bi poznala dar Božji in kdo je, ki ti pravi: Daj mi piti, prosila bi ti njega, in dal bi ti žive vode.',
        11: 'Reče mu žena: Gospod, saj še zajeti nimaš s čim, in vodnjak je globok: odkod imaš torej živo vodo?',
        12: 'Si mar ti večji od našega očeta Jakoba, ki nam je dal ta vodnjak, in je sam iz njega pil in sinovi njegovi in živina njegova?',
        13: 'Jezus odgovori in ji reče: Vsak, kdor pije od te vode, bo zopet žejen;',
        14: 'kdorkoli pa se napije vode, ki mu jo jaz dam, ne bo žejen vekomaj, temuč voda, ki mu jo jaz dam, postane v njem studenec vode, ki teče v večno življenje.',
        15: 'Reče mu žena: Gospod, daj mi te vode, da ne bom žejna in da ne bom hodila semkaj zajemat.',
        16: 'Veli ji Jezus: Pojdi, pokliči moža svojega in pridi sem.',
        17: 'Žena odgovori in reče: Nimam moža. Reče ji Jezus: Prav si povedala: Nimam moža.',
        18: 'Imela si namreč pet mož, in tisti, ki ga imaš sedaj, ni tvoj mož: to si po pravici povedala.',
        19: 'Reče mu žena: Gospod, vidim, da si prorok.',
        20: 'Očetje naši so na tej gori molili; vi pa pravite, da je v Jeruzalemu kraj, kjer se mora moliti.',
        21: 'Reče ji Jezus: Žena, verjemi mi, da prihaja ura, ko ne boste molili Očeta ne na tej gori, ne v Jeruzalemu.',
        22: 'Vi molite, česar ne veste; mi molimo, kar vemo: zakaj zveličanje pride od Judov.',
        23: 'Ali prihaja ura in je že sedaj, ko bodo pravi molilci molili Očeta v duhu in resnici; saj Oče tudi išče takih, da bi ga molili.',
        24: 'Bog je duh, in kateri ga molijo, morajo moliti v duhu in resnici.',
        25: 'Reče mu žena: Vem, da pride Mesija (ki se imenuje Kristus); kadar on pride, nam vse oznani.',
        26: 'Reče ji Jezus: Jaz sem, ki govorim s teboj.',
        27: 'In v tem pridejo učenci njegovi in se čudijo, da se pogovarja z ženo; vendar pa nihče ne reče: Kaj hočeš? ali: Kaj se pogovarjaš ž njo?',
        28: 'Žena torej pusti svoj vrč in odide v mesto in veli ljudem:',
        29: 'Pridite, poglejte človeka, ki mi je povedal vse, kar sem storila, ali ni ta Kristus?',
        30: 'In gredo iz mesta in pridejo k njemu.',
        31: 'Medtem so ga pa učenci prosili, rekoč: Rabi, jej!',
        32: 'On jim pa reče: Jaz imam jed, da jo jem, za katero vi ne veste.',
        33: 'Učenci se torej pomenkujejo med seboj: Ali mu je kdo prinesel jesti?',
        34: 'Reče jim Jezus: Moja jed je, da izpolnjujem voljo tega, ki me je poslal, in dopolnim delo njegovo.',
        35: 'Ne pravite li vi, da je še štiri mesece, pa pride žetev? Glej, pravim vam, povzdignite oči in poglejte njive, da so že bele za žetev.',
        36: 'Kdor žanje, prejema plačilo in zbira sad za večno življenje, da se skupaj radujeta, kdor seje in kdor žanje.',
        37: 'Kajti v tem je pregovor resničen: Drugi je, ki seje, in drugi, ki žanje.',
        38: 'Jaz sem vas poslal žet, česar vi niste obdelali; drugi so obdelali, in vi ste prišli v njih delo.',
        39: 'Iz tega mesta je pa mnogo Samarijanov sprejelo vero vanj zavoljo besede žene, ki je pričala: Povedal mi je vse, kar sem storila.',
        40: 'Ko pridejo torej Samarijani k njemu, ga prosijo, naj ostane pri njih. In ostal je tam dva dni.',
        41: 'In veliko več jih je sprejelo vero zavoljo njegove besede.',
        42: 'A ženi so pravili: Sedaj ne verujemo več zavoljo tvojega govorjenja, kajti sami smo slišali in vemo, da je ta resnično Zveličar sveta, Kristus.',
        43: 'Po teh dveh dneh pa gre odtod v Galilejo.',
        44: 'Kajti Jezus sam je pričal, da prorok nima časti v svoji domovini.',
        45: 'Ko pa pride v Galilejo, ga sprejmo Galilejci, ker so videli vse, kar je storil v Jeruzalemu ob prazniku; bili so namreč tudi prišli na praznik.',
        46: 'In zopet pride Jezus v Kano Galilejsko, kjer je bil izpremenil vodo v vino. In bil je neki kraljev uradnik, čigar sin je bil bolan, v Kafarnavmu.',
        47: 'Ko ta sliši, da je prišel Jezus iz Judeje v Galilejo, gre k njemu in ga prosi, naj pride doli in mu ozdravi sina; ta je namreč umiral.',
        48: 'Reče mu torej Jezus: Če znamenj in čudežev ne vidite, ne boste verovali.',
        49: 'Reče mu kraljev uradnik: Gospod, pojdi doli, preden umrje otrok moj.',
        50: 'Veli mu Jezus: Pojdi, sin tvoj je živ. Mož veruje besedi, ki mu jo je Jezus rekel, in gre.',
        51: 'Ko pa je že na potu doli, ga srečajo hlapci njegovi in mu sporoče, da sin njegov živi.',
        52: 'Vpraša jih torej, obkore mu je odleglo. In mu reko: Včeraj ob sedmi uri ga je pustila mrzlica.',
        53: 'Tedaj spozna oče, da je bilo tisto uro, ko mu je Jezus rekel: Sin tvoj je živ. In je sprejel vero on in vsa hiša njegova.',
        54: 'To je drugi čudež, ki ga je zopet storil Jezus, ko je prišel iz Judeje v Galilejo.',
    },
    5: {
        1: 'Potem je bil praznik Judov in Jezus se napoti v Jeruzalem.',
        2: 'V Jeruzalemu je pa pri Ovčjih vratih kopel, ki se hebrejski imenuje Betezda, in ima pet lop.',
        3: 'V teh je ležala množica bolnikov, slepih, hromih, sušičnih, ki so pričakovali gibanja vode.',
        4: 'Prihajal je namreč angel ob svojem času v kopel in je kalil vodo; in kdor je prvi stopil v vodo, potem ko se je bila skalila, je ozdravel, katerokoli bolezen je imel.',
        5: 'Bil je pa tam neki človek, ki je bil osemintrideset let bolan.',
        6: 'Ko ga Jezus vidi, da leži, in zve, da je že dolgo časa bolan, mu reče: Hočeš li ozdraveti?',
        7: 'Bolnik mu odgovori: Gospod, nimam človeka, da bi me, kadar se voda skali, posadil v kopel; a preden sam pridem, stopi vanjo drugi pred menoj.',
        8: 'Veli mu Jezus: Vstani, vzemi posteljo svojo in hodi.',
        9: 'In precej je mož ozdravel, in vzame posteljo svojo in hodi. Bila pa je tisti dan sobota.',
        10: 'Zatorej reko Judje ozdravljenemu: Sobota je, in ne smeš postelje nositi.',
        11: 'On pa jim odgovori: Ta, ki me je ozdravil, mi je rekel: Vzemi posteljo svojo in hodi.',
        12: 'Vprašajo ga: Kdo je tisti človek, ki ti je rekel: Vzemi posteljo in hodi?',
        13: 'Ozdravljenec pa ni vedel, kdo je bil; zakaj Jezus se je umaknil, ker je bilo veliko ljudstva v tem kraju.',
        14: 'Potem ga najde Jezus v templju in mu reče: Glej, ozdravljen si, ne greši več, da se ti kaj hujšega ne prigodi.',
        15: 'Človek odide in sporoči Judom, da je Jezus tisti, ki ga je ozdravil.',
        16: 'In zato so Judje preganjali Jezusa, ker je to delal v soboto.',
        17: 'Jezus jim je pa odgovoril: Oče moj dela doslej, tudi jaz delam.',
        18: 'Zato pa so Judje še bolj gledali, da bi ga umorili, ker ni le sobote prelomil, marveč tudi Boga je imenoval svojega Očeta, delajoč se enakega Bogu.',
        19: 'Jezus torej odgovori in jim reče: Resnično, resnično vam pravim: Sin ne more sam od sebe ničesar delati, razen kar vidi, da dela Oče; karkoli namreč dela on, to tudi Sin dela prav tako.',
        20: 'Kajti Oče ljubi Sina in mu kaže vse, kar sam dela, in še večja dela nego ta mu pokaže, da bi se vi čudili.',
        21: 'Kakor namreč Oče obuja mrtve in oživlja, tako tudi Sin oživlja, katere hoče.',
        22: 'Kajti Oče tudi ne sodi nikogar, temuč vso sodbo je izročil Sinu,',
        23: 'da bi vsi častili Sina, kakor časté Očeta; kdor ne časti Sina, ne časti Očeta, ki ga je poslal.',
        24: 'Resnično, resnično vam pravim, kdor posluša mojo besedo in veruje temu, ki me je poslal, ima večno življenje, in ne pride na sodbo, temuč je že prešel iz smrti v življenje.',
        25: 'Resnično, resnično vam pravim, da pride ura in je že zdaj, ko mrtvi zaslišijo glas Sinu Božjega, in kateri zaslišijo, bodo živeli.',
        26: 'Zakaj kakor ima Oče življenje v sebi, tako je dal tudi Sinu, da ima življenje v sebi.',
        27: 'In dal mu je oblast tudi soditi, ker je sin človečji.',
        28: 'Ne čudite se temu; kajti pride ura, ob kateri zaslišijo vsi, ki so v grobih, glas njegov',
        29: 'in pridejo ven: kateri so delali dobro, na vstajenje življenja, in kateri so delali hudo, na vstajenje sodbe.',
        30: 'Jaz ne morem sam od sebe ničesar delati. Kakor slišim, tako sodim, in sodba moja je pravična, ker ne iščem svoje volje, ampak voljo tega, ki me je poslal.',
        31: 'Ako sam za sebe pričam, pričevanje moje ni resnično.',
        32: 'Drugi je, ki pričuje zame, in vem, da je resnično pričevanje, ki ga daje zame.',
        33: 'Vi ste poslali k Janezu, in on je pričal za resnico.',
        34: 'Ali jaz ne sprejemam pričevanja, ki je od človeka; ali pravim to, da se vi zveličate.',
        35: 'On je bil svetiljka, ki je gorela in svetila: vam pa je bilo po volji, da se nekaj časa veselite svetlobe njegove.',
        36: 'Ali jaz imam večje pričevanje nego Janezovo: dela namreč, katera mi je Oče izročil, da jih dopolnim, prav ta dela, ki jih jaz delam, pričajo zame, da me je Oče poslal.',
        37: 'In Oče, ki me je poslal, je sam pričal zame. Niste nikoli slišali njegovega glasu, ne videli njegovega obličja;',
        38: 'in besede njegove nimate, da bi prebivala v vas: ker temu, ki ga je on poslal, ne verujete.',
        39: 'Preiskujete pisma, ker mislite, da imate v njih večno življenje, in ta so, ki pričajo zame;',
        40: 'a nočete priti k meni, da bi imeli življenje.',
        41: 'Slave od ljudi ne sprejemam.',
        42: 'Ali poznam vas, da nimate ljubezni Božje v sebi.',
        43: 'Jaz sem prišel v Očeta svojega imenu, in me ne sprejemate; če kdo drugi pride v svojem imenu, njega sprejmete.',
        44: 'Kako morete verovati, ko sprejemate slavo drug od drugega, slave pa, ki je od edinega Boga, ne iščete?',
        45: 'Ne mislite, da vas bom jaz tožil pri Očetu; je že, ki vas toži: Mojzes, ki ste nanj postavili upanje svoje.',
        46: 'Ko bi namreč verovali Mojzesu, bi verovali meni; zakaj on je pisal o meni.',
        47: 'Če pa njegovim pismom ne verujete, kako boste mojim besedam verjeli?',
    },
    6: {
        1: 'Potem odide Jezus na oni kraj morja Galilejskega ali Tiberijskega.',
        2: 'In za njim je šla velika množica, ker so videli njegove čudeže, ki jih je delal na bolnikih.',
        3: 'Jezus pa gre na goro in tu sede z učenci svojimi.',
        4: 'Bila je pa blizu Velika noč, praznik Judov.',
        5: 'Ko torej povzdigne Jezus oči in vidi, da velika množica prihaja k njemu, reče Filipu: Kje naj kupimo kruha, da bodo ti jedli?',
        6: 'To pa je rekel, da ga izkuša; kajti on je vedel, kaj hoče storiti.',
        7: 'Filip mu odgovori: Za dvesto denarjev kruha jim ni dosti, da bi vsak izmed njih dobil kaj malega.',
        8: 'Reče mu eden učencev njegovih, Andrej, Simona Petra brat:',
        9: 'Deček je tu, ki ima pet ječmenovih hlebov in dve ribi; ali kaj je to med toliko?',
        10: 'Jezus veli: Naredite, da se ljudje posadé. Bilo je pa veliko trave na tem mestu. In posadé se možje, kakih pet tisoč po številu.',
        11: 'Tedaj vzame Jezus hlebe in ko zahvali, jih razdeli učencem, učenci pa tem, ki so sedeli; ravno tako jim dá tudi od ribic, kolikor so hoteli.',
        12: 'Ko se pa nasitijo, veli učencem svojim: Zberite ostale kosce, da nič ne pogine.',
        13: 'Zbero torej in napolnijo dvanajst košev koscev od petih hlebov ječmenovih, ki so ostali tem, ki so jedli.',
        14: 'Ko torej vidijo ljudje čudež, ki ga je Jezus storil, govore: Ta je res prorok, ki ima priti na svet.',
        15: 'Jezus torej, ker spozna, da hočejo priti in ga siloma odvesti, da ga postavijo za kralja, se zopet umakne na goro, on sam.',
        16: 'Ko se pa zvečeri, gredo učenci njegovi k morju,',
        17: 'in stopivši v ladjo, se popeljejo na oni kraj morja v Kafarnavm. In tema je že nastala, in Jezus še ni prišel k njim;',
        18: 'in morje je bilo razburkano, ker je pihal močan veter.',
        19: 'Ko pa veslajo kakih petindvajset ali trideset tečajev daleč, ugledajo Jezusa, da hodi po morju in se približuje ladji, in se preplašijo.',
        20: 'On pa jim reče: Jaz sem; ne bojte se!',
        21: 'Hočejo ga torej vzeti v ladjo; in precej je bila ladja pri kraju, kamor so se peljali.',
        22: 'Drugi dan, ko vidi ljudstvo, ki je stalo onkraj morja, da ni bilo tam druge ladjice razen tiste ene, ki so vanjo vstopili učenci, in da Jezus ni stopil z učenci svojimi v ladjo, ampak da so bili učenci sami odšli,',
        23: '(prišle so pa druge ladjice iz Tiberije blizu h kraju, kjer so bili jedli kruh, ko je Gospod zahvalil),',
        24: 'ko torej ljudstvo izprevidi, da Jezusa ni tu in tudi učencev njegovih ne: stopijo tudi oni v ladjice in pridejo v Kafarnavm, da poiščejo Jezusa.',
        25: 'In ko ga najdejo onkraj morja, mu reko: Rabi, kdaj si prišel sem?',
        26: 'Odgovori jim Jezus in reče: Resnično, resnično vam pravim, iščete me ne zato, ker ste videli čudeže, temuč ker ste jedli od hlebov in ste se nasitili.',
        27: 'Trudite se ne za jed, ki mine, ampak za jed, ki ostane v večno življenje, ki vam jo dá Sin človekov: zakaj njega je potrdil Oče, Bog.',
        28: 'Reko mu torej: Kaj naj storimo, da delamo dela Božja?',
        29: 'Jezus jim odgovori in reče: To je delo Božje, da verujete v tega, ki ga je on poslal.',
        30: 'Pa mu reko: Kakšno znamenje torej pokažeš, da bi videli in verovali? kaj delaš?',
        31: 'Očetje naši so jedli mano v puščavi, kakor je pisano: „Kruh iz nebes jim je dal jesti“.',
        32: 'Jezus jim pa reče: Resnično, resnično vam pravim: Ne Mojzes vam je dal kruha iz nebes, marveč Oče moj vam daje pravi kruh iz nebes.',
        33: 'Kruh Božji namreč je ta, ki prihaja iz nebes in daje življenje svetu.',
        34: 'Reko mu torej: Gospod, daj nam vsekdar tega kruha.',
        35: 'Jezus jim reče: Jaz sem kruh življenja: kdor prihaja k meni, ne bo nikoli lačen, in kdor veruje v me, ne bo nikdar žejen.',
        36: 'Ali povedal sem vam, da ste me videli, in vendar ne verujete.',
        37: 'Vse, kar mi daje Oče, pride k meni, in tega, ki k meni prihaja, ne pahnem ven.',
        38: 'Zakaj stopil sem iz nebes, ne da bi delal svojo voljo, marveč voljo tega, ki me je poslal.',
        39: 'To pa je volja tega, ki me je poslal, da ničesar ne izgubim od tega, kar mi je dal, temuč da vse to obudim poslednji dan.',
        40: 'Kajti to je volja Očeta mojega, da ima večno življenje vsak, kdor vidi Sina in veruje vanj, in jaz ga obudim poslednji dan.',
        41: 'Tedaj godrnjajo Judje nad njim, da je rekel: Jaz sem kruh, ki je prišel iz nebes,',
        42: 'in govore: Ali ni ta Jezus, sin Jožefov, čigar očeta in mater poznamo? Kako da sedaj pravi: Iz nebes sem prišel?',
        43: 'Jezus odgovori in reče: Ne godrnjajte med seboj.',
        44: 'Nihče ne more priti k meni, če ga ne vleče Oče, ki me je poslal, in jaz ga obudim poslednji dan.',
        45: 'Pisano je v prorokih: „In vsi bodo učeni od Boga“. Vsak, ki je slišal Očeta in se je naučil, prihaja k meni.',
        46: 'Ne pravim, da je kdo videl Očeta, razen tisti, ki je od Boga: ta je videl Očeta.',
        47: 'Resnično, resnično vam pravim: Kdor veruje, ima večno življenje.',
        48: 'Jaz sem kruh življenja.',
        49: 'Očetje vaši so jedli mano v puščavi in so pomrli.',
        50: 'Ta je kruh, ki prihaja iz nebes, da ne umre, kdor jé od njega.',
        51: 'Jaz sem živi kruh, ki je prišel iz nebes; če kdo jé od tega kruha, bo živel vekomaj. Kruh pa, ki ga jaz dam, je moje meso, ki ga dam za življenje sveta.',
        52: 'Judje se pa prepirajo med seboj, govoreč: Kako nam more ta dati svoje meso jesti?',
        53: 'Jezus jim pa reče: Resnično, resnično vam pravim: Če ne jeste mesa Sinu človekovega in ne pijete njegove krvi, nimate življenja v sebi.',
        54: 'Kdor jé moje meso in pije mojo kri, ima večno življenje, in jaz ga obudim poslednji dan.',
        55: 'Kajti meso moje je prava jed in kri moja je prava pijača.',
        56: 'Kdor jé moje meso in pije mojo kri, prebiva v meni in jaz v njem.',
        57: 'Kakor je mene poslal živi Oče in jaz živim zaradi Očeta: tako bo tudi tisti, ki mene jé, živel zaradi mene.',
        58: 'Ta je kruh, ki je prišel iz nebes; ne kakor so Očetje vaši jedli in so pomrli: kdor jé ta kruh, bo živel vekomaj.',
        59: 'To je povedal v shodnici, ko je učil v Kafarnavmu.',
        60: 'Mnogi torej učencev njegovih, ko so to slišali, reko: Trda je ta beseda; kdo jo more poslušati?',
        61: 'Vedoč pa sam v sebi, da učenci njegovi godrnjajo nad tem, jim reče Jezus: To vam je v spotiko?',
        62: 'Kaj pa, ko boste videli Sina človekovega, da gre gori, kjer je bil poprej?',
        63: 'Duh je to, kar oživlja, meso ne pomaga nič; besede, ki sem vam jih jaz govoril, so duh in so življenje.',
        64: 'Toda so med vami nekateri, ki ne verujejo. Jezus je namreč od začetka vedel, kateri so, ki ne verujejo, in kdo je, ki ga izda.',
        65: 'In reče: Zato sem vam rekel, da ne more nihče priti k meni, če mu ni dano od Očeta mojega.',
        66: 'Vsled tega je mnogo učencev njegovih odstopilo in nič več niso hodili ž njim.',
        67: 'Reče torej Jezus dvanajsterim: Ali hočete tudi vi oditi?',
        68: 'Simon Peter mu odgovori: Gospod, h komu pojdemo? Besede večnega življenja imaš ti.',
        69: 'In mi smo verovali in vemo, da si ti Svetnik Božji.',
        70: 'Odgovori jim Jezus: Ali nisem jaz vas dvanajsterih izvolil? In eden izmed vas je hudič.',
        71: 'To pa je rekel o Judu, sinu Simona Iškariota; kajti ta ga je imel izdati, eden izmed dvanajsterih.',
    },
    7: {
        1: 'In poten je Jezus hodil po Galileji; kajti po Judeji ni hotel hoditi, ker so Judje gledali, da bi ga umorili.',
        2: 'Bil je pa blizu judovski praznik šatorov.',
        3: 'Zato mu reko bratje njegovi: Idi odtod in pojdi v Judejo, da tudi učenci tvoji vidijo dela tvoja, ki jih delaš.',
        4: 'Zakaj nihče, ki hoče biti javno poznan, ne dela ničesar na skrivnem. Če take reči delaš, pokaži se svetu.',
        5: 'Tudi bratje njegovi namreč niso verovali vanj.',
        6: 'Reče jim torej Jezus: Moj čas še ni prišel; vaš čas pa je vsekdar prikladen.',
        7: 'Vas ne more svet sovražiti; mene pa sovraži, ker jaz pričujem o njem, da so dela njegova hudobna.',
        8: 'Vi pojdite na praznik; jaz še ne grem na ta praznik, ker se moj čas še ni dopolnil.',
        9: 'In ko jim je to povedal, je ostal v Galileji.',
        10: 'Ko so pa bratje njegovi odšli na praznik, tedaj odide tudi on, ne očitno, temuč kakor skrivaj.',
        11: 'Judje so ga torej iskali ob prazniku in govorili: Kje je tisti?',
        12: 'In bilo je dosti govorjenja o njem med množicami. Nekateri so pravili: Dober je; drugi pa so trdili: Ne, ampak ljudstvo slepari.',
        13: 'Vendar pa nihče ni očitno govoril o njem zavoljo strahu pred Judi.',
        14: 'Ko je pa minilo že pol praznika, vstopi Jezus v tempelj in uči.',
        15: 'In Judje se čudijo ter pravijo: Kako je ta učen v pismih, ko se ni šolal?',
        16: 'Odgovori jim torej Jezus in reče: Moj nauk ni moj, ampak tega, ki me je poslal.',
        17: 'Če hoče kdo njegovo voljo izpolnjevati, razpozna, je li ta nauk iz Boga ali če jaz sam od sebe govorim.',
        18: 'Kdor govori sam od sebe, išče lastne slave; kdor pa išče slave tega, ki ga je poslal, ta je resničen in nepravičnosti ni v njem.',
        19: 'Vam li ni Mojzes dal postave? In vendar nihče iz vas ne izpolnjuje postave. Zakaj gledate, da bi me umorili?',
        20: 'Ljudstvo odgovori: Hudiča imaš! Kdo gleda, da bi te umoril?',
        21: 'Jezus odgovori in jim reče: Eno delo sem storil, in vsi se čudite temu.',
        22: 'Mojzes vam je dal obrezo (ne da se je od Mojzesa začela, ampak od očakov), in v soboto obrezujete človeka.',
        23: 'Če prejme človek obrezo v soboto, da se ne prelomi postava Mojzesova, zakaj se nad menoj hudujete, da sem celega človeka ozdravil v soboto?',
        24: 'Ne sodite po licu, ampak sodite pravično sodbo!',
        25: 'Tedaj reko nekateri izmed Jeruzalemcev: Ali ni ta tisti, ki gledajo, da bi ga umorili?',
        26: 'In glejte, očitno govori in nič mu ne reko. Ali so mar poglavarji v resnici spoznali, da je ta Kristus?',
        27: 'Toda za tega vemo, odkod je; za Kristusa pa, kadar pride, ne bo nihče vedel, odkod je.',
        28: 'Jezus torej zakliče, učeč v templju, in reče: Poznate me in tudi veste, odkod sem; in sam od sebe nisem prišel: je pa resničen, ki me je poslal, katerega vi ne poznate.',
        29: 'Jaz ga poznam, ker sem od njega, in on me je poslal.',
        30: 'Gledali so torej, da bi ga zgrabili; ali nihče ni položil nanj roke, ker ura njegova še ni bila prišla.',
        31: 'Mnogi pa izmed ljudstva so sprejeli vero vanj; in so govorili: Ali bo Kristus, kadar pride več čudežev storil, nego jih je ta storil?',
        32: 'Farizeji zaslišijo, da si ljudstvo to o njem šepeče; in višji duhovniki in farizeji pošljejo služabnike, naj ga ujemo.',
        33: 'Reče torej Jezus: Še malo časa sem z vami, in pojdem k temu, ki me je poslal.',
        34: 'Iskali me boste, a me ne najdete; in kjer sem jaz, tja vi ne morete priti.',
        35: 'Tedaj reko Judje med seboj: Kam pojde ta, da ga mi ne najdemo? Ali pojde k tem, ki so razkropljeni med Grki, in bo učil Grke?',
        36: 'Kakšna je ta beseda, ki jo je rekel: Iskali me boste, a me ne najdete, in kjer sem jaz, vi ne morete priti?',
        37: 'A poslednji veliki dan praznika je stal Jezus in klical, rekoč: Če je kdo žejen, naj pride k meni in pije.',
        38: 'Kdor veruje v mene, kakor pravi pismo, reke žive vode poteko iz telesa njegovega.',
        39: 'To je pa rekel o Duhu, ki so ga imeli prejeti ti, ki so verovali vanj; Duh namreč še ni bil dan, ker Jezus še ni bil oslavljen.',
        40: 'Nekateri iz množice, čujoč te besede, reko torej: Ta je zares prorok.',
        41: 'Drugi pravijo: Ta je Kristus. Drugi pa govore: Ali pride Kristus iz Galileje?',
        42: 'Ali ne pravi pismo, da pride Kristus iz semena Davidovega in iz trga Betlehema, kjer je bil David?',
        43: 'Nastane torej razpor med ljudstvom zaradi njega.',
        44: 'A nekateri izmed njih so ga hoteli zgrabiti; pa nihče ni položil nanj rok.',
        45: 'In služabniki pridejo k višjim duhovnikom in farizejem; in ti jim reko: Zakaj ga niste pripeljali?',
        46: 'Služabniki odgovore: Nikoli noben človek ni tako govoril.',
        47: 'Farizeji pa jim odgovore: Ali ste tudi vi zapeljani?',
        48: 'Je li kdo izmed prvakov sprejel vero vanj, ali izmed farizejev?',
        49: 'Ampak ta druhal, ki ne pozna zakona; prokleti so!',
        50: 'Reče jim Nikodem, ki je bil prej prišel k njemu in je bil eden izmed njih:',
        51: 'Ali postava naša sodi človeka, če ga prej ne zaslišijo in se ne izve, kaj dela?',
        52: 'Odgovore in mu reko: Si li mar tudi ti iz Galileje? Preišči in poglej, da iz Galileje ne vstane noben prorok. [',
        53: 'In odidejo vsak na svoj dom.',
    },
    8: {
        1: 'Jezus pa gre na Oljsko goro.',
        2: 'A zjutraj pride zopet v tempelj. In vse ljudstvo se zbere k njemu, in sede ter jih uči.',
        3: 'Pripeljejo pa pismarji in farizeji k njemu ženo, v prešeštvu zasačeno, jo postavijo na sredo',
        4: 'in mu reko: Učenik, ta žena je ravnokar v prešeštvu zasačena.',
        5: 'V postavi pa nam je Mojzes zapovedal, naj take s kamenjem posujemo. Ti torej kaj praviš?',
        6: 'To pa govore, izkušajoč ga, da bi ga mogli zatožiti. A Jezus se skloni ter piše s prstom po tleh.',
        7: 'Ko pa le še vprašujejo, se zravna in jim reče: Kdor je med vami brez greha, naj prvi vrže kamen nanjo.',
        8: 'In zopet se skloni in piše po tleh.',
        9: 'Oni pa, ko so to slišali, odhajajo drug za drugim, počenši od starejših, celo do zadnjih. In Jezus ostane sam in žena, na sredi stoječ.',
        10: 'Jezus pa, ko se zravna pokonci in razen žene ne vidi nikogar, ji reče: Žena, kje so oni? ali te ni nobeden obsodil?',
        11: 'Ona pa reče: Nobeden, Gospod. A Jezus ji reče: Tudi jaz te ne obsojam; pojdi in odslej več ne greši!]',
        12: 'Jezus jim torej zopet govori, rekoč: Jaz sem luč sveta; kdor gre za menoj, ne bo hodil po temi, temuč bo imel luč življenja.',
        13: 'Reko mu pa farizeji: Ti sam zase pričuješ; pričevanje tvoje ni resnično.',
        14: 'Jezus odgovori in jim reče: Čeprav jaz sam zase pričujem, je resnično pričevanje moje, ker vem, odkod sem prišel in kam grem; vi pa ne veste, odkod sem prišel in kam grem.',
        15: 'Vi po mesu sodite; jaz ne sodim nikogar.',
        16: 'Če pa tudi sodim, je resnična sodba moja; zakaj nisem sam, marveč jaz in Oče, ki me je poslal.',
        17: 'Pisano pa je tudi v zakonu vašem, da je dveh človekov pričevanje resnično.',
        18: 'Jaz sem, ki pričujem sam zase, in pričuje zame Oče, ki me je poslal.',
        19: 'Reko mu tedaj: Kje je tvoj Oče? Jezus odgovori: Niti mene ne poznate niti Očeta mojega; ko bi mene poznali, poznali bi tudi Očeta mojega.',
        20: 'Te besede je govoril pri zakladnici, učeč v templju; in nihče ga ni zgrabil, ker še ni bila prišla ura njegova.',
        21: 'In Jezus jim zopet reče: Jaz odhajam, in iskali me boste in v grehu svojem umrjete. Kamor jaz grem, vi ne morete priti.',
        22: 'Judje torej govore: Ali se sam umori, da pravi: Kamor jaz grem, vi ne morete priti?',
        23: 'In jim reče: Vi ste od zdolaj, jaz sem odzgoraj; vi ste od tega sveta, jaz nisem od tega sveta.',
        24: 'Zatorej sem vam rekel, da umrjete v grehih svojih; če namreč ne boste verovali, da sem jaz, umrjete v grehih svojih.',
        25: 'Reko mu torej: Kdo si? Reče jim Jezus: To, kar vam že od začetka pravim.',
        26: 'Mnogo imam o vas govoriti in soditi; ali ta, ki me je poslal, je resničen; in jaz govorim svetu to, kar sem od njega slišal.',
        27: 'Niso pa spoznali, da jim je govoril o Očetu.',
        28: 'Zato reče Jezus: Kadar boste povišali Sina človekovega, tedaj spoznate, da sem jaz in da sam od sebe ničesar ne delam, temuč kakor me je naučil Oče moj, to govorim.',
        29: 'In ta, ki me je poslal, je z menoj; ni me pustil samega, zakaj jaz delam vsekdar to, kar je njemu pogodi.',
        30: 'Ko je to govoril, jih je mnogo sprejelo vero vanj.',
        31: 'Tedaj govori Jezus tistim Judom, ki so mu verovali: Če vi ostanete v besedi moji, bodete zares učenci moji,',
        32: 'in spoznate resnico, in resnica vas osvobodi.',
        33: 'Odgovore mu: Seme Abrahamovo smo in nikomur še nismo nikdar sužnjevali; kako praviš ti: Postanete svobodni?',
        34: 'Jezus jim odgovori: Resnično, resnično vam pravim, da vsak, kdor dela greh, je suženj grehu.',
        35: 'Suženj pa ne ostane v hiši vekomaj; sin ostane vekomaj.',
        36: 'Če vas torej Sin osvobodi, bodete res svobodni.',
        37: 'Vem, da ste seme Abrahamovo; ali gledate, kako bi me umorili, ker beseda moja nima mesta v vas.',
        38: 'Jaz govorim, kar sem videl pri svojem Očetu; tudi vi torej delate, kar ste od svojega očeta slišali.',
        39: 'Odgovore in mu reko: Oče naš je Abraham. Reče jim Jezus: Ko bi bili sinovi Abrahamovi, bi delali Abrahamova dela.',
        40: 'Sedaj pa gledate, kako bi me umorili, človeka, ki sem vam povedal resnico, ki sem jo slišal od Boga: tega Abraham ni storil.',
        41: 'Vi delate očeta svojega dela. Pa mu reko: Mi nismo iz nečistosti rojeni; enega Očeta imamo, Boga.',
        42: 'Jezus jim reče: Ko bi bil Bog vaš Oče, bi ljubili mene, zakaj jaz sem od Boga izšel in prišel; nisem namreč sam od sebe prišel, temuč on me je poslal.',
        43: 'Zakaj govora mojega ne umete? Ker ne morete moje besede poslušati.',
        44: 'Vi ste iz očeta hudiča in želje očeta svojega hočete izpolnjevati. On je bil ubijalec ljudi od začetka, in na resnici ne stoji, ker resnice ni v njem. Kadar govori laž, govori iz lastnega, ker je lažnik in oče laži.',
        45: 'Ker pa jaz govorim resnico, mi ne verujete.',
        46: 'Kdo izmed vas me more dolžiti greha? Če pa resnico govorim, zakaj mi vi ne verujete?',
        47: 'Kdor je iz Boga, posluša Božje besede; zato vi ne poslušate, ker niste iz Boga.',
        48: 'Judje odgovore in mu reko: Ali ne pravimo prav, da si Samarijan in imaš zlega duha?',
        49: 'Jezus odgovori: Jaz nimam zlega duha, ampak častim Očeta svojega; a vi me onečaščujete.',
        50: 'Jaz pa ne iščem svoje slave; je eden, ki je išče in sodi.',
        51: 'Resnično, resnično vam pravim: ako kdo ohrani besedo mojo, ne bo videl smrti vekomaj.',
        52: 'Reko mu Judje: Sedaj smo spoznali, da imaš zlega duha. Abraham je umrl in proroki, a ti praviš: Ako kdo ohrani besedo mojo, ne okusi smrti vekomaj.',
        53: 'Kaj si nemara ti večji od našega očeta Abrahama, ki je umrl? Tudi proroki so pomrli. Koga se ti sam delaš?',
        54: 'Jezus odgovori: Če se jaz sam slavim, slava moja ni nič: Oče moj je, ki me slavi, o katerem vi pravite, da je vaš Bog;',
        55: 'a niste ga spoznali, jaz pa ga poznam, in ko bi rekel, da ga ne poznam, bi bil lažnivec, vam enak. Ali poznam ga in besedo njegovo izpolnjujem.',
        56: 'Abraham, oče vaš, se je veselil, da bo videl moj dan; in videl ga je in se je vzradoval.',
        57: 'Reko mu torej Judje: Petdeset let še nimaš, in Abrahama si videl?',
        58: 'Jezus jim reče: Resnično, resnično vam pravim: Preden je bil Abraham, sem jaz.',
        59: 'Tedaj pograbijo za kamenje, da bi ga lučali vanj. Ali Jezus se skrije in odide iz templja.',
    },
    9: {
        1: 'In gredoč mimo, ugleda človeka, ki je bil slep od rojstva.',
        2: 'In vprašajo ga učenci njegovi, rekoč: Rabi, kdo je grešil: ta ali roditelji njegovi, da se je slep rodil?',
        3: 'Jezus odgovori: Grešil ni ne ta, ne roditelji njegovi, temuč da se razodenejo dela Božja na njem.',
        4: 'Jaz moram delati dela tega, ki me je poslal, dokler je dan; pride noč, ko nihče ne bo mogel delati.',
        5: 'Dokler sem na svetu, sem luč sveta.',
        6: 'Rekši to, pljune na zemljo in napravi blato iz sline in pomaže z blatom slepcu oči',
        7: 'in mu reče: Pojdi, umij se v kopeli Siloamu (kar se tolmači: Poslan). Odide torej in se umije, ter se vrne z vidom.',
        8: 'A sosedje, in kateri so ga prej videli, da je bil berač, govore: Ni li ta, ki je sedel in prosjačil?',
        9: 'Drugi pravijo: On je; drugi pa: Ni, le podoben mu je. Sam pravi: Jaz sem.',
        10: 'Reko mu torej: Kako pa so se ti odprle oči?',
        11: 'On odgovori: Človek, ki se imenuje Jezus, je napravil blato, in mi je pomazal oči in mi rekel: Pojdi v Siloam in umij se. Šel sem torej in se umil, in sem izpregledal.',
        12: 'Reko mu: Kje je on? Reče: Ne vem.',
        13: 'Peljejo ga k farizejem, tega, ki je bil nekdaj slep.',
        14: 'Bila je pa sobota tisti dan, ko je Jezus naredil blato in mu odprl oči.',
        15: 'Zdaj ga torej vprašujejo tudi farizeji, kako je izpregledal. On jim pa reče: Blato mi je dal na oči, in umil sem se in vidim.',
        16: 'Tedaj reko nekateri izmed farizejev: Ta človek ni od Boga, ker sobote ne posvečuje. Drugi pravijo: Kako more človek grešnik take čudeže delati? In razpor je bil med njimi.',
        17: 'Zopet reko slepcu: Kaj ti praviš o njem, ker ti je odprl oči? On pa reče: Prorok je.',
        18: 'Judje torej niso verjeli, da je bil slep in da je izpregledal, dokler niso poklicali roditeljev tega, ki je izpregledal.',
        19: 'In jih vprašajo, rekoč: Je li vaš ta sin, ki o njem pravite, da se je slep rodil? Kako pa sedaj vidi?',
        20: 'Odgovore jim roditelji njegovi in reko: Vemo, da je ta sin naš in da se je slep rodil;',
        21: 'kako pa sedaj vidi, ne vemo, ali kdo mu je oči odprl, tudi ne vemo. Njega vprašajte, leta ima, naj govori sam zase.',
        22: 'To so rekli roditelji njegovi zato, ker so se bali Judov; zakaj Judje so se bili že dogovorili, naj se izobči iz shodnice, kdor bi ga pripoznal za Kristusa.',
        23: 'Zato so roditelji njegovi rekli: Leta ima, njega vprašajte.',
        24: 'Pokličejo torej drugič človeka, ki je bil slep, in mu reko: Daj Bogu čast! mi vemo, da je ta človek grešnik.',
        25: 'On pa odgovori: Če je grešnik, ne vem; eno vem, da sem bil slep, in da sedaj vidim.',
        26: 'Reko mu torej: Kaj ti je storil? Kako ti je odprl oči?',
        27: 'Odgovori jim: Saj sem vam že povedal, in niste slišali; čemu hočete zopet slišati? Ali hočete tudi vi postati njegovi učenci?',
        28: 'Oni pa ga opsujejo in reko: Ti si njegov učenec; mi smo Mojzesovi učenci.',
        29: 'Mi vemo, da je z Mojzesom govoril Bog; za tega pa ne vemo, odkod je.',
        30: 'Človek odgovori in jim reče: To je pa res čudno, da vi ne veste, odkod je, in vendar mi je odprl oči!',
        31: 'Vemo pa, da grešnikov Bog ne sliši, ampak če kdo časti Boga in izpolnjuje voljo njegovo, tega sliši.',
        32: 'Od vekomaj se ni slišalo, da bi bil kdo odprl oči od rojstva slepemu.',
        33: 'Ko ta ne bi bil od Boga, ne bi mogel ničesar storiti.',
        34: 'Odgovore in mu reko: Ves v grehih si se rodil, pa boš ti nas učil? In ga pahnejo ven.',
        35: 'Jezus zasliši, da so ga vrgli ven, in ko ga najde, mu reče: Veruješ li v Sina Božjega?',
        36: 'On odgovori in reče: In kdo je, Gospod, da bi veroval vanj?',
        37: 'Jezus mu reče: Videl si ga, in ki s teboj govori, ta je.',
        38: 'On pa reče: Verujem, Gospod! in ga moli.',
        39: 'In Jezus veli: Na sodbo sem prišel jaz na ta svet, da izpregledajo, kateri ne vidijo, in kateri vidijo, da oslepe.',
        40: 'In slišijo to izmed farizejev tisti, ki so bili ž njim, in mu reko: Ali smo tudi mi slepi?',
        41: 'Jezus jim reče: Ko bi bili slepi, ne bi imeli greha; sedaj pa pravite: Vidimo; zato greh vaš ostaja.',
    },
    10: {
        1: 'Resnično, resnično vam pravim: Kdor ne vhaja skozi vrata v ovčji hlev, ampak lazi drugod vanj, ta je tat in razbojnik.',
        2: 'Kdor pa vhaja skozi vrata, ta je pastir ovac.',
        3: 'Temu vratar odpira, in ovce poslušajo glas njegov, in svoje ovce kliče po imenu in jih vodi na pašo.',
        4: 'Ko vse ovce svoje izpusti, gre pred njimi, in ovce gredo za njim, ker poznajo glas njegov;',
        5: 'a za tujcem ne gredo, temuč beže od njega, ker ne poznajo glasu tujcev.',
        6: 'To priliko jim je povedal Jezus, ali oni niso razumeli, kaj bi bilo to, kar jim je pravil.',
        7: 'Jezus jim torej zopet reče: Resnično, resnično vam pravim, da sem jaz vrata k ovcam.',
        8: 'Vsi, kolikor jih je prišlo pred menoj, so tatje in razbojniki; ali ovce jih niso poslušale.',
        9: 'Jaz sem vrata: skozi mene če kdo gre noter, bo zveličan, in bo hodil noter in ven in najde pašo.',
        10: 'Tat ne pride, razen da krade in kolje in pokonča; jaz sem prišel, da imajo življenje in da imajo obilo.',
        11: 'Jaz sem dobri pastir. Dobri pastir dá svoje življenje za ovce.',
        12: 'Najemnik pa, ki ni pastir, ki mu ovce niso lastne, vidi volka, da gre in zapusti ovce in zbeži, in volk trga in razganja ovce,',
        13: 'on pa beži, ker je najemnik, in ne mara za ovce.',
        14: 'Jaz sem dobri pastir, in poznam svoje in moje poznajo mene:',
        15: 'kakor Oče mene pozna in jaz Očeta poznam; in življenje svoje dam za ovce.',
        16: 'In imam še drugih ovac, ki niso iz tega hleva; tudi te moram pripeljati, in bodo poslušale moj glas, in bode ena čreda, eden pastir.',
        17: 'Zato me Oče ljubi, ker jaz dam življenje svoje, da ga zopet vzamem.',
        18: 'Nihče ga ne jemlje od mene, marveč jaz ga dajem sam od sebe. Oblast imam, da ga dam, in oblast imam, da ga zopet vzamem. To zapoved sem prejel od Očeta svojega.',
        19: 'Med Judi nastane zopet razpor zavoljo teh besed.',
        20: 'Mnogi izmed njih pa govore: Zlega duha ima in ob pamet je, kaj ga poslušate?',
        21: 'Drugi pravijo: Te besede ne morejo prihajati od obsedenca; ali more zli duh slepcem odpirati oči?',
        22: 'Bil pa je praznik posvečenja templja v Jeruzalemu, in bila je zima.',
        23: 'In Jezus se je izprehajal v templju po lopi Salomonovi.',
        24: 'Obstopijo ga torej Judje in mu reko: Doklej nas pustiš v negotovosti? Če si ti Kristus, povej nam naravnost!',
        25: 'Odgovori jim Jezus: Povedal sem vam, pa ne verujete. Dela, ki jih jaz delam v imenu Očeta svojega, ta pričajo zame.',
        26: 'Toda vi ne verujete, ker niste izmed mojih ovac.',
        27: 'Moje ovce poslušajo glas moj, in jaz jih poznam, in za menoj hodijo;',
        28: 'in jaz jim dajem večno življenje, in nikdar se ne pogube, in nihče jih ne iztrga iz moje roke.',
        29: 'Oče moj, ki mi jih je dal, je večji od vsega, in nihče jih ne more iztrgati iz roke Očeta mojega.',
        30: 'Jaz in Oče sva eno.',
        31: 'Judje zopet pograbijo za kamenje, da bi ga kamenali.',
        32: 'Odgovori jim Jezus: Veliko dobrih del sem vam pokazal od Očeta svojega; za katero teh del me kamenate?',
        33: 'Judje mu odgovore: Za dobro delo te ne kamenamo, ampak za kletvino, in ker se ti, ki si človek, delaš Boga.',
        34: 'Jezus jim odgovori: Ni li pisano v zakonu vašem: „Jaz sem rekel: bogovi ste“?',
        35: 'Če je imenoval bogove tiste, ki je prišla beseda Božja k njim, in pismo se ne more ovreči,',
        36: 'zakaj pa meni, ki me je Oče posvetil in na svet poslal, pravite vi: Preklinjaš, ker sem rekel: Sin Božji sem?',
        37: 'Ako ne delam del Očeta svojega, mi ne verujte;',
        38: 'ako pa delam, čeprav meni ne verujete, vsaj delom verujte: da spoznate in verujete, da je Oče v meni in jaz v Očetu.',
        39: 'In zopet poskušajo, da bi ga prijeli, ali umakne se jim izpod rok.',
        40: 'In odide zopet na oni kraj Jordana, na mesto, kjer je prej Janez krščeval; in ostane tu.',
        41: 'In mnogo jih pride k njemu; in pravijo: Janez res ni storil nobenega čudeža, ali karkoli je Janez povedal za tega, je bilo vse resnično.',
        42: 'In mnogo jih je tu sprejelo vero vanj.',
    },
    11: {
        1: 'Bil je pa eden bolan, po imenu Lazar, iz Betanije, iz trga Marije in Marte, njene sestre.',
        2: 'Marija, katere brat Lazar je bil bolan, pa je bila ta, ki je pomazilila Gospoda z mazilom in mu utrla noge z lasmi svojimi.',
        3: 'Sestri torej pošljeta k njemu, rekoč: Gospod, glej, ki ga ti ljubiš, je bolan.',
        4: 'Ko pa Jezus sliši, reče: Ta bolezen ni za smrt, marveč za slavo Božjo, da se Sin Božji po njej oslavi.',
        5: 'Jezus je pa ljubil Marto in njeno sestro in Lazarja.',
        6: 'Ko torej zasliši, da je bolan, tedaj ostane še dva dni na tistem mestu, kjer je bil.',
        7: 'Potem šele veli učencem svojim: Pojdimo zopet v Judejo!',
        8: 'Učenci mu reko: Rabi, ravnokar so te hoteli Judje s kamenjem posuti, pa pojdeš zopet tja?',
        9: 'Jezus odgovori: Nima li dan dvanajst ur? Če kdo po dnevi hodi, se ne spotakne, ker vidi luč tega sveta;',
        10: 'če pa kdo po noči hodi, se spotakne, ker ni luči v njem.',
        11: 'To je povedal, in potem reče: Lazar, prijatelj naš, je zaspal; pa grem, da ga prebudim.',
        12: 'Reko mu torej učenci njegovi: Gospod, če je zaspal, ozdravi.',
        13: 'Rekel pa je to Jezus o smrti njegovi; a oni so mislili, da pravi o navadnem spanju.',
        14: 'Tedaj jim Jezus razločno pove: Lazar je umrl;',
        15: 'in radujem se zavoljo vas, da nisem bil tam, da boste verovali; pa pojdimo k njemu.',
        16: 'Tedaj reče Tomaž, ki se imenuje Dvojček, součencem: Pojdimo še mi, da umremo ž njim.',
        17: 'Ko torej Jezus pride, ga najde že štiri dni ležečega v grobu.',
        18: 'Bila je pa Betanija blizu Jeruzalema, kakih petnajst tečajev.',
        19: 'In mnogo izmed Judov jih je bilo prišlo k Marti in Mariji, da bi ju tolažili po njunem bratu.',
        20: 'Ko torej zasliši Marta, da prihaja Jezus, mu gre naproti; a Marija je doma sedela.',
        21: 'Marta torej reče Jezusu: Gospod, ko bi bil ti tukaj, brat moj ne bi bil umrl.',
        22: 'A tudi sedaj vem, karkoli poprosiš Boga, ti Bog da.',
        23: 'Reče ji Jezus: Brat tvoj vstane.',
        24: 'Marta mu reče: Vem, da vstane ob vstajenju poslednji dan.',
        25: 'Reče ji Jezus: Jaz sem vstajenje in življenje; kdor v mene veruje, bo živel, čeprav umre;',
        26: 'in vsak, kdor živi in veruje vame, ne umre vekomaj. Veruješ li to?',
        27: 'Reče mu: Da, Gospod, verujem, da si ti Kristus, Sin Božji, ki je imel priti na svet.',
        28: 'In rekši to, odide in pokliče skrivaj Marijo, sestro svojo, rekoč: Učenik je tu in te kliče.',
        29: 'Ona pa, ko zasliši, hitro vstane in pride k njemu.',
        30: 'Jezus namreč še ni bil prišel v trg, temuč je bil še na mestu, kjer ga je bila Marta srečala.',
        31: 'Ko pa vidijo Judje, ki so bili ž njo v hiši in so jo tolažili, da je Marija hitro vstala in odšla, gredo za njo, misleč, da gre h grobu, da bi tam jokala.',
        32: 'Ko torej pride Marija tja, kjer je Jezus, in ga ugleda, mu pade k nogam in mu reče: Gospod, ko bi bil ti tukaj, brat moj ne bi bil umrl.',
        33: 'Jezus pa, ko jo vidi, da joka, in Judje, ki so prišli ž njo, da jokajo, se zgrozi v duhu in postane sam žalosten,',
        34: 'in reče: Kam ste ga položili? Reko mu: Pridi in poglej!',
        35: 'Jezus se razjoka.',
        36: 'Judje tedaj reko: Glej, kako ga je ljubil!',
        37: 'A nekateri izmed njih reko: Ali ni mogel on, ki je slepemu oči odprl, storiti, da bi tudi ta ne bil umrl?',
        38: 'In Jezus se zopet zgrozi v sebi in pride h grobu. Bila je pa votlina in kamen je ležal na njej.',
        39: 'Jezus veli: Vzdignite kamen! Marta, sestra rajnikova, mu reče: Gospod, že smrdi; zakaj štiri dni je že v grobu.',
        40: 'Veli ji Jezus: Ali ti nisem rekel, da boš videla slavo Božjo, če veruješ?',
        41: 'Tedaj odvalijo kamen, kjer je mrtvec ležal. A Jezus povzdigne oči kvišku in reče: Oče, zahvaljujem te, da si me uslišal.',
        42: 'Pa jaz sem vedel, da me vsekdar poslušaš; toda zaradi ljudstva, ki okoli stoji, sem to rekel, da bi verovali, da si me ti poslal.',
        43: 'In ko je to rekel, zakliče z močnim glasom: Lazar, pridi ven!',
        44: 'In mrtvec izide, povezan na nogah in rokah s povoji, in njegov obraz je bil obvezan s prtom. Veli jim Jezus: Razvežite ga in pustite, naj odide.',
        45: 'Tedaj jih je veliko izmed Judov, ki so bili prišli k Mariji in so videli, kaj je Jezus storil, sprejelo vero vanj.',
        46: 'A nekateri izmed njih odidejo k farizejem in jim povedo, kaj je storil Jezus.',
        47: 'Višji duhovniki in farizeji torej skličejo veliki zbor in reko: Kaj čemo storiti? kajti ta človek dela veliko čudežev.',
        48: 'Če ga tako pustimo, bodo vsi verovali vanj; in pridejo Rimljani in nam vzemo i zemljo i narod.',
        49: 'A eden izmed njih, Kajfa, ki je bil tisto leto veliki duhovnik, jim reče: Vi ničesar ne veste,',
        50: 'in tudi ne premišljate, da je bolje za vas, če eden človek umre za ljudstvo, nego da bi ves narod poginil.',
        51: 'Tega pa ni rekel sam od sebe, temuč, ker je bil tisto leto veliki duhovnik, je prorokoval, da ima Jezus umreti za narod;',
        52: 'in ne samo za ta narod, ampak da tudi razkropljene otroke Božje zbere v eno.',
        53: 'Od tega dne torej se posvetujejo, kako naj ga umore.',
        54: 'Jezus pa ni hodil več očitno med Judi, temuč se je umaknil odtod v kraj blizu puščave, k mestu, ki se imenuje Efraim; in tu je prebival z učenci svojimi.',
        55: 'Bila je pa blizu Velika noč Judov; in veliko jih gre iz dežele gori v Jeruzalem pred Veliko nočjo, da se očistijo.',
        56: 'Iščejo tedaj Jezusa in se pogovarjajo med seboj, stoječ v templju: Kaj se vam zdi? Gotovo ne pride na praznik?',
        57: 'Izdali pa so višji duhovniki in farizeji zapoved, če kdo zve, kje je, naj to naznani, da bi ga zgrabili.',
    },
    12: {
        1: 'Šest dni pred Veliko nočjo pa Pride Jezus v Betanijo, kjer je bil Lazar, ki je bil umrl in ga je Jezus obudil iz mrtvih.',
        2: 'In napravijo mu tu večerjo; in Marta je stregla, Lazar pa je bil eden med temi, ki so ž njim sedeli za mizo.',
        3: 'Marija pa vzame libro nardovega mazila, pravega in dragocenega, in pomazili noge Jezusove in mu jih otre z lasmi svojimi; in hiša se napolni z duhom mazila.',
        4: 'Toda Juda Simonov Iškariot, eden učencev njegovih, ki ga je imel izdati, reče:',
        5: 'Zakaj se ni prodalo to mazilo za tristo denarjev in dalo ubogim?',
        6: 'To pa je rekel, ne ker ga je bila skrb za uboge, ampak ker je bil tat in je imel mošnjo in nosil, kar so metali vanjo.',
        7: 'Jezus pa reče: Pusti jo; za dan pogreba mojega je to prihranila.',
        8: 'Kajti uboge imate vsekdar pri sebi, a mene nimate vsekdar.',
        9: 'Zvedelo je pa preprosto ljudstvo izmed Judov, da je tukaj, ter pridejo ne samo zaradi Jezusa, ampak da bi tudi videli Lazarja, ki ga je bil obudil iz mrtvih.',
        10: 'Višji duhovniki pa se posvetujejo, da bi tudi Lazarja umorili;',
        11: 'ker so mnogi izmed Judov hodili tja zavoljo njega in so sprejemali vero v Jezusa.',
        12: 'Drugi dan zasliši velika množica, ki je bila prišla na praznik, da gre Jezus v Jeruzalem.',
        13: 'In vzemo palmove veje in mu pridejo naproti in vpijejo: Hosana! Blagoslovljen, ki prihaja v imenu Gospodovem, kralj Izraelov!',
        14: 'In Jezus dobi osliča in sede nanj, kakor je pisano:',
        15: '„Ne boj se, hči sionska! glej, kralj tvoj gre, sedeč na žrebetu osličjem.“',
        16: 'Tega učenci njegovi izprva niso razumeli, ampak ko je bil Jezus oslavljen, tedaj so se spomnili, da je bilo to pisano za njega in da so mu to storili.',
        17: 'Ljudstvo torej, ki je bilo ž njim, ko je Lazarja poklical iz groba in ga obudil iz mrtvih, je pričevalo o njem.',
        18: 'Zato mu je tudi množica prišla naproti, ker so slišali, da je storil ta čudež.',
        19: 'Farizeji reko tedaj med seboj: Vidite, da nič ne opravite! Glej, ves svet leti za njim.',
        20: 'Bili so pa nekateri Grki med tistimi, ki so prihajali, da bi molili o prazniku.',
        21: 'Ti torej pristopijo k Filipu, ki je bil iz Betsaide Galilejske, in ga zaprosijo, rekoč: Gospod, Jezusa bi radi videli.',
        22: 'Filip gre in pove to Andreju, in Andrej in Filip povesta Jezusu.',
        23: 'Jezus pa jima odgovori, rekoč: Prišla je ura, da bi bil oslavljen Sin človekov.',
        24: 'Resnično, resnično vam pravim: Pšenično zrno, če pade v zemljo in ne umre, ostane samo; če pa umre, obrodi veliko sadu.',
        25: 'Kdor ljubi dušo svojo, jo izgubi; a kdor sovraži dušo svojo na tem svetu, jo ohrani za večno življenje.',
        26: 'Ako mi hoče kdo služiti, naj gre za menoj; in kjer sem jaz, tam bo tudi služabnik moj; in če kdo meni služi, njega počasti Oče.',
        27: 'Sedaj je duša moja žalostna, in kaj hočem reči? Oče, reši me iz te ure! Toda prav zato sem prišel v to uro.',
        28: 'Oče, oslavi ime svoje! Tedaj se oglasi glas z neba: Oslavil sem ga, in zopet ga oslavim.',
        29: 'Ljudstvo torej, ki je zraven stalo in je to slišalo, pravi, da je zagrmelo. Drugi pravijo: Angel mu je govoril.',
        30: 'Jezus odgovori in reče: Ne zaradi mene je prišel ta glas, ampak zavoljo vas.',
        31: 'Zdaj je sodba tega sveta; zdaj bo vojvoda tega sveta vržen ven.',
        32: 'In jaz, kadar bom povišan od zemlje, vse potegnem k sebi.',
        33: 'To je pa pravil, da naznači, s kakšno smrtjo mu je umreti.',
        34: 'Ljudstvo mu torej odgovori: Mi smo slišali iz zakona, da Kristus ostane vekomaj, in kako praviš ti, da mora biti povišan Sin človekov? Kdo je ta Sin človekov?',
        35: 'Jezus jim torej reče: Še malo časa je luč med vami. Hodite, dokler imate luč, da vas ne objame tema; in kdor po temi hodi, ne ve, kam gre.',
        36: 'Dokler imate luč, verujte v luč, da postanete sinovi luči. To je Jezus povedal, in je odšel in se skril pred njimi.',
        37: 'In dasi je toliko čudežev storil vpričo njih, niso verovali vanj,',
        38: 'da se izpolni beseda Izaija proroka, ki jo je rekel: „Gospod, kdo je veroval našemu poročilu? in rama Gospodova komu se je razodela?“',
        39: 'Verovati pa zato niso mogli, ker je zopet rekel Izaija:',
        40: '„Oslepil jim je oči in zakrknil jim je srce, da ne bi z očmi videli in s srcem umeli in se izpreobrnili, in jaz bi jih ozdravil.“',
        41: 'To je rekel Izaija, ko je videl slavo njegovo in je govoril o njem.',
        42: 'Vendar so pa tudi mnogi izmed prvakov verovali vanj, toda zaradi farizejev niso priznavali, da ne bi bili izobčeni iz shodnice.',
        43: 'Kajti ljubili so slavo pri ljudeh bolj nego slavo pri Bogu.',
        44: 'Jezus pa zakliče in reče: Kdor veruje v mene, veruje ne v mene, marveč v tega, ki me je poslal.',
        45: 'In kdor vidi mene, vidi tega, ki me je poslal.',
        46: 'Jaz Luč sem prišel na svet, da ne ostane v temi nihče, kdor veruje v mene.',
        47: 'In če kdo sliši moje besede in jih ne hrani, jaz ga ne sodim; zakaj nisem prišel, da bi svet sodil, ampak da zveličam svet.',
        48: 'Kdor zaničuje mene in ne sprejema besed mojih, ima svojega sodnika: beseda, ki sem jo govoril, ona ga bo sodila v poslednji dan.',
        49: 'Kajti jaz nisem sam od sebe govoril, temuč Oče, ki me je poslal, on mi je dal zapoved, kaj naj povem in kaj naj govorim.',
        50: 'In vem, da je njegova zapoved večno življenje. Kar torej jaz govorim, govorim tako, kakor mi je Oče rekel.',
    },
    13: {
        1: 'Pred praznikom velikonočnim pa, ko je Jezus vedel, da je prišla njegova ura, da prejde s tega sveta k Očetu: ker je ljubil svoje, ki so bili na svetu, jih je ljubil do konca.',
        2: 'In pri večerji, ko je že bil hudič Judu Simonovemu Iškariotu dal v srce, naj ga izda,',
        3: 'vstane Jezus, vedoč, da mu je dal Oče vse v roke, in da je od Boga izšel in k Bogu gre,',
        4: 'od večerje in sleče oblačilo in vzame prt ter se opaše.',
        5: 'Potem vlije vode v medenico in začne umivati učencem noge in otirati s prtom, ki je bil ž njim opasan.',
        6: 'Pride torej k Simonu Petru. On mu reče: Gospod, ti mi boš umival noge?',
        7: 'Jezus odgovori in mu reče: Kar jaz delam, ti sedaj ne veš, ali zvedel boš potem.',
        8: 'Reče mu Peter: Ne boš mi umival nog, na vekomaj ne! Odgovori mu Jezus: Če te ne umijem, nimaš deleža z menoj.',
        9: 'Reče mu Simon Peter: Gospod, ne samo nog mojih, ampak tudi roke in glavo!',
        10: 'Reče mu Jezus: Kdor je bil v kopeli umit, ne potrebuje, samo da si noge umije, sicer je ves čist; in vi ste čisti, ali ne vsi.',
        11: 'Poznal je namreč izdajalca svojega; zato je rekel: Niste vsi čisti.',
        12: 'Ko jim je torej umil noge in je vzel oblačilo svoje, sede zopet za mizo in jim reče: Veste li, kaj sem vam storil?',
        13: 'Vi me zovete: Učenik in Gospod, in prav pravite; kajti to tudi sem.',
        14: 'Če sem torej jaz, Gospod in Učenik, vam umil noge, ste dolžni tudi vi drug drugemu umivati noge.',
        15: 'Zgled sem vam dal namreč, da tudi vi delajte tako, kakor sem vam jaz storil.',
        16: 'Resnično, resnično vam pravim: Hlapec ni večji od gospodarja svojega, tudi poslanec ni večji nego tisti, ki ga je poslal.',
        17: 'Ako to veste, blagor vam, če to delate.',
        18: 'Ne govorim o vseh vas; jaz vem, katere sem izvolil. Ali izpolniti se mora pismo: „Ta, ki jé z menoj kruh, je vzdignil peto svojo zoper mene.“',
        19: 'Že sedaj vam to pravim, preden se je zgodilo, da verujete, kadar se zgodi, da sem jaz.',
        20: 'Resnično, resnično vam pravim: Kdor ga sprejme, kogarkoli pošljem, sprejme mene; kdor pa sprejme mene, sprejme tega, ki me je poslal.',
        21: 'Ko je Jezus to povedal, se razžalosti v duhu, ter zatrdi in reče: Resnično, resnično vam pravim, da me eden izmed vas izda.',
        22: 'Učenci se tedaj spogledujejo med seboj, pomišljujoč, o katerem pravi.',
        23: 'Slonel je pa za mizo na naročju Jezusovem eden učencev njegovih, ki ga je Jezus ljubil.',
        24: 'Simon Peter torej namigne temu in mu reče: Povej nam, kdo je, o katerem pravi.',
        25: 'On se nasloni, kakor je, Jezusu na prsi ter mu reče: Gospod, kdo je?',
        26: 'Jezus odgovori: Ta je, ki mu grižljaj omočim in podam. Omočivši torej grižljaj, ga vzame in poda Judu Simonovemu Iškariotu.',
        27: 'In za grižljajem - tedaj vnide vanj satan. Jezus mu torej veli: Kar delaš, stori hitro.',
        28: 'Tega pa ni razumel nobeden za mizo sedečih, čemu mu je to rekel.',
        29: 'Nekateri so namreč mislili, ker je Juda mošnjo imel, da mu Jezus pravi: Nakupi, kar nam je treba za praznik: ali da naj dá kaj ubogim.',
        30: 'Vzemši torej grižljaj, odide takoj; bila je pa noč.',
        31: 'Ko je torej odšel, reče Jezus: Sedaj je Sin človekov oslavljen, in Bog je oslavljen v njem.',
        32: 'Če je Bog oslavljen v njem, ga tudi Bog oslavi v sebi, in precej ga oslavi.',
        33: 'Otročiči, še malo časa sem z vami. Iskali me boste, a kakor sem Judom povedal: kamor jaz grem, vi ne morete priti, tako pravim sedaj tudi vam.',
        34: 'Novo zapoved vam dajem, da se ljubite med seboj; kakor sem jaz vas ljubil, da se tudi vi ljubite med seboj.',
        35: 'V tem spoznajo vsi, da ste moji učenci, ako imate ljubezen drug do drugega.',
        36: 'Reče mu Simon Peter: Gospod, kam greš? Jezus odgovori: Kamor grem, ne moreš zdaj iti za menoj; pozneje pa pojdeš za menoj.',
        37: 'Reče mu Peter: Gospod, zakaj ne morem sedaj iti za teboj? Življenje svoje dam zate.',
        38: 'Jezus odgovori: Življenje svoje daš zame? Resnično, resnično ti pravim: Petelin ne zapoje, dokler me trikrat ne zatajiš.',
    },
    14: {
        1: 'Ne bodi vam srce plašno. Verujte v Boga, tudi v mene verujte.',
        2: 'V hiši Očeta mojega je veliko prebivališč. Če bi ne bilo, bi vam bil povedal; kajti grem pripravljat vam prostora!',
        3: 'In ko odidem in vam pripravim prostor, pridem zopet in vas vzamem k sebi, da boste tudi vi tam, kjer sem jaz.',
        4: 'In kam jaz grem, veste, tudi pot veste.',
        5: 'Reče mu Tomaž: Gospod, ne vemo, kam greš, in kako moremo vedeti pot?',
        6: 'Veli mu Jezus: Jaz sem pot in resnica in življenje; nihče ne pride k Očetu razen po meni.',
        7: 'Ko bi bili mene spoznali, bi poznali tudi Očeta mojega. In odsihdob ga poznate, in videli ste ga.',
        8: 'Reče mu Filip: Gospod, pokaži nam Očeta, in dosti je nam.',
        9: 'Jezus mu dé: Toliko časa sem z vami, in nisi me spoznal, Filip? Kdor je mene videl, je videl Očeta; in kako ti praviš: Pokaži nam Očeta?',
        10: 'Ne veruješ li, da sem jaz v Očetu in Oče v meni? Besed, ki jih vam jaz pravim, ne govorim sam od sebe, ampak Oče, ki v meni prebiva, on vrši dela svoja.',
        11: 'Verujte mi, da sem jaz v Očetu in Oče v meni; če pa ne, verujte mi vsaj zavoljo teh del.',
        12: 'Resnično, resnično vam pravim: Kdor veruje v mene, bo tudi on vršil dela, ki jih jaz delam, in bo vršil še večja od teh: kajti jaz grem k Očetu.',
        13: 'In karkoli boste prosili v mojem imenu, to bom storil, da bo oslavljen Oče v Sinu.',
        14: 'Če boste kaj prosili v mojem imenu, jaz bom storil.',
        15: 'Ako me ljubite, boste izpolnjevali zapovedi moje.',
        16: 'In jaz bom prosil Očeta, in drugega Tolažnika vam dá, da ostane z vami vekomaj,',
        17: 'Duha resnice, ki ga svet ne more prejeti, ker ga ne vidi in ga tudi ne pozna; vi ga pa poznate, ker pri vas prebiva, in bode v vas.',
        18: 'Ne pustim vas sirot, pridem k vam.',
        19: 'Še malo, in svet me več ne bo videl, a vi me boste videli: ker jaz živim, boste tudi vi živeli.',
        20: 'Tisti dan spoznate, da sem jaz v Očetu svojem, in vi v meni, in jaz v vas.',
        21: 'Kdor ima zapovedi moje in jih izpolnjuje, on je ta, ki me ljubi; kdor pa mene ljubi, ga bo ljubil Oče moj, in jaz ga bom ljubil in mu razodenem sebe.',
        22: 'Reče mu Juda (ne Iškariot): Gospod, kaj se je zgodilo, da hočeš sebe razodeti nam in ne svetu?',
        23: 'Jezus odgovori in mu reče: Če me kdo ljubi, bo izpolnjeval besedo mojo, in Oče moj ga bo ljubil, in k njemu pridemo in prebivališče si napravimo pri njem.',
        24: 'Kdor me ne ljubi, mojih besed ne izpolnjuje; in beseda, ki jo slišite, ni moja, marveč Očeta, ki me je poslal.',
        25: 'To sem vam govoril, dokler sem z vami.',
        26: 'Tolažnik pa, sveti Duh, ki ga pošlje Oče v imenu mojem, on vas bo vse učil in vas spominjal vsega, kar sem vam povedal.',
        27: 'Mir vam zapuščam, mir svoj vam dajem; ne dajem vam jaz, kakor daje svet. Ne bodi vam srce plašno in boječe.',
        28: 'Slišali ste, da sem vam jaz rekel: Grem, a zopet pridem k vam. Ko bi me ljubili, bi se veselili, da grem k Očetu; kajti Oče je večji od mene.',
        29: 'In sedaj sem vam povedal, preden se zgodi, da boste verovali, kadar se zgodi.',
        30: 'Ne bom veliko več govoril z vami: prihaja namreč vojvoda tega sveta, a na meni nima ničesar;',
        31: 'ampak da svet spozna, da ljubim Očeta, in kakor mi je Oče zapovedal, tako delam. Vstanite, pojdite odtod!',
    },
    15: {
        1: 'Jaz sem prava trta, in Oče moj je vinogradnik.',
        2: 'Vsako mladiko na meni, ki ne rodi sadu, odreže; in vsako, ki rodi sad, očiščuje, da bo rodila več sadu.',
        3: 'Vi ste že čisti zavoljo besede, ki sem vam jo govoril.',
        4: 'Ostanite v meni, in jaz v vas. Kakor mladika sama od sebe ne more roditi sadu, če ne ostane na trti: tako tudi vi ne, če ne ostanete v meni.',
        5: 'Jaz sem trta, vi mladike. Kdor ostaja v meni in jaz v njem, ta rodi veliko sadu: zakaj brez mene ne morete ničesar storiti.',
        6: 'Ako kdo ne ostane v meni, bo vržen ven kakor mladika in se posuši: in zbero jih in vržejo na ogenj, in goré.',
        7: 'Če ostanete v meni in besede moje ostanejo v vas: prosite, karkoli hočete, in se vam zgodi.',
        8: 'S tem se bo oslavil Oče moj, da obrodite veliko sadu, in tako bodete moji učenci.',
        9: 'Kakor je Oče mene ljubil, sem tudi jaz ljubil vas: ostanite v tej moji ljubezni.',
        10: 'Če boste izpolnjevali zapovedi moje, ostanete v ljubezni moji; kakor sem jaz izpolnil zapovedi Očeta svojega in ostajam v ljubezni njegovi.',
        11: 'To sem vam povedal, da moja radost ostane v vas in da se vaša radost dopolni.',
        12: 'Moja zapoved je ta, da se ljubite med seboj, kakor sem vas jaz ljubil.',
        13: 'Večje ljubezni od te nima nihče, da kdo dá življenje svoje za prijatelje svoje.',
        14: 'Vi ste prijatelji moji, ako delate, kar vam ukazujem.',
        15: 'Ne imenujem vas več hlapcev, ker hlapec ne ve, kaj dela gospodar njegov; toda vas sem imenoval prijatelje, ker sem vam oznanil vse, kar sem slišal od Očeta svojega.',
        16: 'Niste izvolili vi mene, temuč jaz sem izvolil vas, in postavil sem vas, da greste in obrodite sad in da sad vaš ostane: da vam dá Oče, karkoli ga boste prosili v mojem imenu.',
        17: 'To vam zapovedujem, da se ljubite med seboj.',
        18: 'Če vas svet sovraži, vedite, da je mene prej sovražil nego vas.',
        19: 'Ko bi bili od sveta, svet bi svoje ljubil; ker pa niste od sveta, temuč sem vas jaz odbral iz sveta, zato vas svet sovraži.',
        20: 'Spominjajte se besede, ki sem jo vam jaz rekel: Hlapec ni večji od gospodarja svojega. Če so mene preganjali, bodo preganjali tudi vas; če so mojo besedo ohranili, ohranijo tudi vašo.',
        21: 'Ali to vse vam bodo delali zavoljo imena mojega, ker ne poznajo tega, ki me je poslal.',
        22: 'Ko ne bi bil prišel in jim ne bi bil govoril, ne bi imeli greha; sedaj pa nimajo izgovora za greh svoj.',
        23: 'Kdor mene sovraži, sovraži tudi Očeta mojega.',
        24: 'Ko ne bi bil storil med njimi del, ki jih nihče drugi ni storil, ne bi imeli greha; sedaj so pa videli in sovražili mene in tudi Očeta mojega.',
        25: 'Ali to se godi, da se izpolni beseda, ki je pisana v njih postavi: „Sovražili so me brez vzroka“.',
        26: 'Kadar pa pride Tolažnik, ki ga vam pošljem od Očeta, Duh resnice, ki izhaja od Očeta, on bo pričeval zame;',
        27: 'pa tudi vi pričujete, ker ste od začetka z menoj.',
    },
    16: {
        1: 'To sem vam povedal, da se ne pohujšate.',
        2: 'Izobčijo vas iz shodnic; pride celo ura, da bo vsak, kdor vas bo moril, menil, da s tem opravlja službo Bogu.',
        3: 'In to vam bodo delali, ker niso spoznali Očeta, ne mene.',
        4: 'Ali to sem vam povedal, da bi se, kadar ta ura pride, spomnili tega, da sem vam jaz to rekel. Tega pa vam od začetka nisem povedal, ker sem še bil z vami.',
        5: 'A sedaj grem k temu, ki me je poslal, in nobeden izmed vas me ne vpraša: Kam greš?',
        6: 'Temuč ker sem vam to povedal, je vam žalost napolnila srce.',
        7: 'Ali jaz vam pravim resnico: Bolje vam je, da jaz odidem. Zakaj, če ne odidem, ne pride Tolažnik k vam; če pa odidem, ga pošljem k vam.',
        8: 'In ko on pride, bo prepričeval svet o grehu in pravičnosti in sodbi;',
        9: 'o grehu namreč, ker ne verujejo v mene;',
        10: 'o pravičnosti pa, ker grem k Očetu, in me ne boste več videli;',
        11: 'o sodbi pa, ker je vojvoda tega sveta obsojen.',
        12: 'Še veliko vam imam povedati, sedaj pa ne morete tega nositi.',
        13: 'Kadar pa on pride, Duh resnice, vas bo vodil v vso resnico; ne bo namreč govoril sam od sebe, temuč kar bo slišal, bo govoril, in oznanjeval vam bo prihodnje reči.',
        14: 'On bo mene oslavil, ker od mojega vzame in vam oznani.',
        15: 'Vse, karkoli ima Oče, je moje; zato sem rekel, da vzame od mojega in vam oznani.',
        16: 'Malo, in ne boste me več videli, in zopet malo, in boste me videli.',
        17: 'Tedaj reko nekateri učencev njegovih med seboj: Kaj je to, kar nam pravi: Malo, in ne boste me videli, in zopet malo, in boste me videli, in: Grem k Očetu.',
        18: 'Govore torej: Kaj je to, kar pravi: malo? Ne vemo, kaj pravi.',
        19: 'Jezus pa spozna, da ga hočejo vprašati, in jim reče: Ali se zato poprašujete med seboj, da sem rekel: Malo, in ne boste me videli, in zopet malo, in boste me videli?',
        20: 'Resnično, resnično vam pravim, da boste jokali vi in plakali, a svet se bo radoval; vi pa bodete žalostni, ali žalost vaša se premeni v radost.',
        21: 'Žena, kadar rodi, ima žalost, ker je prišla njena ura; toda ko porodi dete, se ne spominja več bridkosti od veselja, da se je rodil človek na svet.',
        22: 'Tako tudi vas sedaj objemlje žalost; pa zopet vas bom videl, in srce vaše se bo radovalo, in radosti vaše vam ne odvzame nihče.',
        23: 'In tisti dan me ne boste ničesar vpraševali. Resnično, resnično vam pravim: Karkoli boste Očeta prosili, dá vam v imenu mojem.',
        24: 'Doslej niste ničesar prosili v imenu mojem. Prosíte in prejmete, da bo radost vaša dopolnjena.',
        25: 'To sem vam povedal v prilikah; ali pride ura, ko vam ne bom več govoril v prilikah, temuč vam bom odkrito oznanjeval o Očetu.',
        26: 'Tisti dan boste v imenu mojem prosili; in ne pravim vam, da bom jaz prosil Očeta za vas.',
        27: 'Zakaj Oče sam vas ljubi, ker ste vi mene ljubili in ste verovali, da sem jaz izšel od Boga.',
        28: 'Izšel sem od Očeta in prišel sem na svet; zopet zapuščam svet in grem k Očetu.',
        29: 'Reko mu učenci njegovi: Glej, sedaj odkrito govoriš in ne praviš nobene prilike.',
        30: 'Sedaj vemo, da veš vse in ti ni treba, da bi te kdo vpraševal. Po tem verujemo, da si od Boga izšel.',
        31: 'Odgovori jim Jezus: Ali sedaj verujete?',
        32: 'Glej, pride ura, in že je prišla, da se razkropite vsak na svojo stran in mene pustite samega; a nisem sam, ker je Oče z menoj.',
        33: 'To sem vam povedal, da imate mir v meni. Na svetu imate bridkost; ali srčni bodite, jaz sem svet premagal.',
    },
    17: {
        1: 'To je povedal Jezus ter povzdigne oči k nebu in reče: Oče, ura je prišla; oslavi Sina svojega, da tudi Sin tvoj tebe oslavi;',
        2: 'kakor si mu dal oblast nad vsem človeštvom, da dá večno življenje vsem, ki si mu jih dal.',
        3: 'Večno življenje je pa to, da spoznajo tebe, edinega resničnega Boga, in katerega si poslal, Jezusa Kristusa.',
        4: 'Jaz sem te oslavil na zemlji; delo sem dokončal, ki si mi ga dal, da ga storim:',
        5: 'in zdaj oslavi ti, Oče, mene sam pri sebi s slavo, ki sem jo imel pri tebi, preden je bil svet.',
        6: 'Razodel sem ime tvoje ljudem, katere si mi dal od sveta. Tvoji so bili, in meni si jih dal, in besedo tvojo so ohranili.',
        7: 'Sedaj vedo, da je vse, karkoli si mi dal, od tebe:',
        8: 'kajti besede, ki si jih meni dal, sem dal njim; in oni so jih sprejeli in spoznali resnično, da sem od tebe izšel, in so verovali, da si me ti poslal.',
        9: 'Jaz prosim zanje; ne prosim za svet, ampak za te, ki si mi jih dal, ker so tvoji;',
        10: 'in vse moje je tvoje, in tvoje je moje; in oslavljen sem v njih.',
        11: 'In nisem več na svetu, a ti so na svetu; jaz pa grem k tebi. Oče sveti! ohrani jih v imenu svojem, katere si mi dal, da bodo eno, kakor mi.',
        12: 'Dokler sem bil ž njimi, sem jih varoval v imenu tvojem; katere si mi dal, sem ohranil, in nobeden izmed njih ni poginil, razen sin pogube, da se izpolni pismo.',
        13: 'Sedaj pa grem k tebi, in to govorim na svetu, da imajo radost mojo dopolnjeno v sebi.',
        14: 'Jaz sem jim dal besedo tvojo, in svet jih je sovražil, ker niso od sveta, kakor jaz nisem od sveta.',
        15: 'Ne prosim, da jih vzemi s sveta, ampak da jih obvaruj zlega.',
        16: 'Od sveta niso, kakor jaz nisem od sveta.',
        17: 'Posveti jih v resnici: tvoja beseda je resnica.',
        18: 'Kakor si mene poslal na svet, sem poslal tudi jaz nje na svet;',
        19: 'in zanje sam sebe posvečujem, da bodo tudi oni posvečeni v resnici.',
        20: 'Ne prosim pa samo za te, ampak tudi za tiste, ki bodo po njih besedi verovali v mene:',
        21: 'da bodo vsi eno; kakor ti, Oče, v meni in jaz v tebi, da bodo tudi oni v nas eno, da bi svet veroval, da si me ti poslal.',
        22: 'In jaz sem slavo, ki si jo meni dal, dal njim, da bodo eno, kakor smo mi eno.',
        23: 'Jaz v njih in ti v meni, da bodo popolnoma združeni v eno, in da spozna svet, da si me ti poslal in si jih ljubil, kakor si mene ljubil.',
        24: 'Oče, katere si mi dal, hočem, kjer sem jaz, da bodo tudi oni z menoj, da vidijo mojo slavo, ki si mi jo dal, ker si me ljubil pred začetkom sveta.',
        25: 'Oče pravični! svet tebe ni spoznal, a jaz sem te spoznal, in ti so spoznali, da si me ti poslal;',
        26: 'in oznanil sem jim ime tvoje, in oznanjeval ga bom: da bode ljubezen, s katero si me ljubil, v njih in jaz v njih.',
    },
    18: {
        1: 'Rekši to, gre Jezus z učenci svojimi iz mesta čez potok Cedron, kjer je bil vrt, in nanj krenejo on in učenci njegovi.',
        2: 'Vedel je pa tudi Juda, njegov izdajalec, o tem kraju, ker je pogostoma Jezus tja zahajal z učenci svojimi.',
        3: 'Juda torej vzame trumo in služabnike od višjih duhovnikov in farizejev in pride tja s svetilnicami in baklami in orožjem.',
        4: 'Jezus pa, ker je vedel vse, kaj nad njega pride, jim gre naproti in reče: Koga iščete?',
        5: 'Odgovore mu: Jezusa Nazarečana. Jezus jim reče: Jaz sem. Stal je pa ž njimi tudi Juda, izdajalec njegov.',
        6: 'Ko jim je torej rekel: Jaz sem, stopijo nazaj in padejo na tla.',
        7: 'Vpraša jih torej zopet: Koga iščete? Oni pa reko: Jezusa Nazarečana.',
        8: 'Jezus odgovori: Rekel sem vam, da sem jaz. Če torej mene iščete, pustite, da ti odidejo.',
        9: 'Da se izpolni beseda, ki jo je bil rekel: Nobenega nisem izgubil izmed teh, ki si mi jih dal.',
        10: 'A Simon Peter je imel meč; izdere ga torej in udari hlapca velikega duhovnika in mu odseka desno uho. Hlapcu pa je bilo ime Malh.',
        11: 'Jezus pa reče Petru: Vtakni meč svoj v nožnico. Ali naj ne pijem keliha, ki mi ga je dal Oče?',
        12: 'Tedaj zgrabijo vojaki in tisočnik in služabniki Judov Jezusa in ga zvežejo;',
        13: 'in peljejo ga najprej k Anu; bil je namreč tast Kajfov, ki je bil tisto leto veliki duhovnik.',
        14: 'Bil je pa Kajfa tisti, ki je bil Judom nasvetoval, da je bolje, da umre eden človek za ljudstvo.',
        15: 'Za Jezusom pa je šel Simon Peter in neki drugi učenec. Ta učenec pa je bil znan z velikim duhovnikom, ter vnide z Jezusom na dvorišče velikega duhovnika.',
        16: 'Peter pa je stal zunaj pri vratih. Tedaj gre ven drugi učenec, znanec velikega duhovnika, in se pomeni z vratarico in pripelje Petra noter.',
        17: 'Dekla vratarica reče torej Petru. Ali nisi tudi ti izmed učencev tega človeka? On pa reče: Nisem.',
        18: 'A hlapci in služabniki so bili zanetili ogenj, ker je bilo mraz, ter so se okoli stojé greli; stal je pa tudi Peter med njimi in se grel.',
        19: 'Veliki duhovnik torej vpraša Jezusa za učence njegove in za nauk njegov.',
        20: 'Jezus mu odgovori: Jaz sem očitno govoril svetu; jaz sem vsekdar učil v shodnici in templju, kjer se vsi Judje shajajo, in skrivaj nisem ničesar govoril.',
        21: 'Kaj vprašuješ mene? Vprašaj tiste, ki so me slišali, kaj sem jim govoril; glej, oni vedo, kaj sem pravil jaz.',
        22: 'Ko je pa to rekel, udari eden služabnikov, ki je stal poleg, Jezusa po licu in reče: Tako odgovarjaš velikemu duhovniku?',
        23: 'Jezus mu odgovori: Če sem hudo govoril, izpričaj, da je hudo; če pa dobro, zakaj me biješ?',
        24: 'Ana ga torej pošlje zvezanega k velikemu duhovniku Kajfu.',
        25: 'Simon Peter pa stoji pri ognju in se greje. Reko mu torej: Ali nisi tudi ti izmed učencev njegovih? On zataji in reče: Nisem.',
        26: 'Eden izmed hlapcev velikega duhovnika, sorodnik tistega, ki mu je bil Peter odsekal uho, reče: Te li nisem jaz videl ž njim na vrtu?',
        27: 'Peter pa zopet utaji, in precej zapoje petelin.',
        28: 'A Jezusa peljejo od Kajfa v sodno palačo. Bilo je pa zjutraj. In oni nočejo stopiti v sodno palačo, da se ne bi oskrunili, temuč da bi jedli velikonočno jagnje.',
        29: 'Pilat torej pride ven k njim in reče: Kakšno tožbo imate zoper tega človeka?',
        30: 'Odgovore in reko: Če ta ne bi bil hudodelnik, ne bi ga bili tebi izročili.',
        31: 'Reče jim torej Pilat: Vzemite ga vi, in sodite ga po svoji postavi. Judje pa mu reko: Mi ne smemo nikogar umoriti.',
        32: 'Da se izpolni Jezusova beseda, ki jo je rekel, ko je naznačil, s kakšno smrtjo mu bode umreti.',
        33: 'Pilat torej gre zopet v sodno palačo, in pokliče Jezusa in mu reče: Si li ti kralj Judov?',
        34: 'Jezus mu odgovori: Praviš li to sam od sebe ali so ti drugi rekli o meni?',
        35: 'Pilat odgovori: Sem mar jaz Jud? Tvoj narod in višji duhovniki so te meni izročili, kaj si storil?',
        36: 'Jezus odgovori: Moje kraljestvo ni od tega sveta; ko bi bilo moje kraljestvo od tega sveta, bi se moji služabniki vojskovali, da ne bi bil Judom izročen; sedaj pa kraljestvo moje ni odtod.',
        37: 'Tedaj mu reče Pilat: Torej kralj si ti? Jezus odgovori: Ti praviš, da sem jaz kralj. Jaz sem zato rojen, in zato sem prišel na svet, da pričam za resnico. Vsak, kdor je od resnice, posluša glas moj.',
        38: 'Pilat mu reče: Kaj je resnica? In ko je to rekel, izide zopet k Judom in jim reče: Jaz ne vidim nobene krivice na njem.',
        39: 'Je pa navada pri vas, da vam enega izpustim na Veliko noč; hočete li torej, da vam izpustim kralja Judov?',
        40: 'Nato zavpijejo vsi, rekoč: Ne tega, ampak Baraba. Bil je pa Baraba razbojnik.',
    },
    19: {
        1: 'Tedaj vzame Pilat Jezusa in ga da bičati.',
        2: 'In vojaki spleto krono iz trnja in mu jo denejo na glavo, in mu oblečejo škrlaten plašč;',
        3: 'in pristopajo k njemu in govore: Zdrav, kralj Judov! in ga bijejo po licu.',
        4: 'Pilat pa zopet gre ven in jim reče: Glej, pripeljem vam ga ven, da spoznate, da ne vidim na njem nobene krivice.',
        5: 'Pride torej Jezus ven, noseč trnjevo krono in škrlatni plašč. In Pilat jim reče: Glejte, človek!',
        6: 'Ko ga pa ugledajo višji duhovniki in služabniki, zavpijejo, rekoč: Križaj, križaj ga! Veli jim Pilat: Vzemite ga vi in križajte; kajti jaz ne vidim nobene krivice na njem.',
        7: 'Odgovore mu Judje: Mi imamo postavo, in po tej postavi mora umreti, ker je sebe Sina Božjega delal.',
        8: 'Ko pa zasliši Pilat to besedo, se zboji še bolj.',
        9: 'In gre zopet v sodno palačo in reče Jezusu: Odkod si ti? Jezus pa mu ne odgovori besede.',
        10: 'Reče mu torej Pilat: Meni ne odgovoriš? Ne veš li, da imam oblast te oprostiti in da imam oblast te križati?',
        11: 'Jezus mu odgovori: Ne bi imel nobene oblasti nad menoj, da ti ni dano od zgoraj; zato ima tisti, ki me je tebi izročil, večji greh.',
        12: 'Vsled tega si Pilat še prizadeva, da bi ga izpustil. A Judje kriče, rekoč: Če tega izpustiš, nisi prijatelj cesarju, zakaj vsak, kdor se dela kralja, nasprotuje cesarju.',
        13: 'Ko torej Pilat zasliši te besede, pripelje ven Jezusa in sede na sodni stol na mestu, ki se imenuje Kameniti tlak, hebrejski pa Gabata.',
        14: 'Bil je pa dan pripravljanja za Veliko noč, okoli šeste ure. In reče Judom: Glej, kralj vaš!',
        15: 'Oni pa zavpijejo: Proč ž njim, proč, križaj ga! Reče jim Pilat: Kralja vašega bom križal? Višji duhovniki odgovore: Nimamo kralja, samo cesarja.',
        16: 'Tedaj jim ga izroči, naj ga križajo. Vzemo torej Jezusa in ga odpeljejo.',
        17: 'In nesoč sam križ svoj, gre ven na mesto, imenovano Mrtvaška glava, ki po hebrejski slove Golgota.',
        18: 'Tu ga razpno na križ in ž njim dva druga, na vsaki strani enega, v sredi pa Jezusa.',
        19: 'Napiše pa Pilat tudi napis in ga dene na križ; bilo je pa pisano: JEZUS NAZAREČAN, KRALJ JUDOV.',
        20: 'Ta napis je torej bralo mnogo Judov, ker je bil kraj, kjer so Jezusa razpeli, blizu mesta; in bilo je pisano hebrejski, grški, latinski.',
        21: 'Reko torej višji duhovniki Judov Pilatu: Ne piši ‚Kralj Judov‘, ampak da je sam rekel ‚Kralj Judov sem‘.',
        22: 'Pilat odgovori: Kar sem pisal, sem pisal.',
        23: 'Vojaki pa, ko so bili Jezusa razpeli, vzemo obleko njegovo in napravijo štiri dele, vsakemu vojaku del, in tudi suknjo; suknja pa ni bila šivana, nego od vrha sceloma stkana.',
        24: 'Zato reko med seboj: Trgali je ne bomo, ampak srečkajmo, čigava bo. Da se izpolni pismo, ki pravi: „Razdelili so obleko mojo med seboj in za suknjo mojo so vrgli kocko“. Vojaki so torej tako storili.',
        25: 'Stale so pa pri križu Jezusovem mati njegova in sestra matere njegove, Marija Klopova, in Marija Magdalena.',
        26: 'Ko torej ugleda Jezus mater in učenca, katerega je ljubil, da tu stoji, reče materi svoji: Žena, glej, sin tvoj!',
        27: 'Potem reče učencu: Glej, mati tvoja! In od tega časa jo je vzel učenec k sebi.',
        28: 'Potem reče Jezus, vedoč, da je že vse dopolnjeno, da se izpolni pismo: Žejen sem.',
        29: 'Stala je tam posoda, polna octa: oni torej nataknejo na izop gobo, namočeno z octom, ter mu jo podado k ustom.',
        30: 'Ko pa Jezus ocet okusi, reče: Dopolnjeno je! in nakloni glavo in izroči duha.',
        31: 'Da pa ne ostanejo trupla v soboto na križu, ker je bil dan pripravljanja (bil je namreč ta sobotni dan velik), zaprosijo Judje Pilata, naj jim goleni prebijejo in jih snamejo.',
        32: 'Vojaki torej pridejo in prebijejo prvemu goleni in drugemu, ki je bil ž njim križan.',
        33: 'Ko pa pridejo do Jezusa in vidijo, da je že umrl, mu ne prelomijo goleni,',
        34: 'temuč eden od vojakov mu prebode s sulico stran, in precej priteče kri in voda iz nje.',
        35: 'In ta, ki je videl, je izpričal, in pričevanje njegovo je resnično, in on ve, da govori resnico, da bi tudi vi verovali.',
        36: 'Kajti to se je zgodilo, da se izpolni pismo: „Nobene kosti mu ne bodo prelomili.“',
        37: 'In zopet drugo pismo pravi: „Gledali ga bodo, ki so ga prebodli.“',
        38: 'Potem pa zaprosi Pilata Jožef iz Arimateje, ki je bil učenec Jezusov, toda skrivaj iz strahu pred Judi, da bi snel truplo Jezusovo; in Pilat dovoli. Pride torej in sname truplo njegovo.',
        39: 'Pride pa tudi Nikodem, ki je bil prvič prišel k Jezusu po noči, in prinese zmesi mire in aloe kakih sto liber.',
        40: 'Vzameta torej truplo Jezusovo in ga zavijeta v prte z dišavami vred, kakor imajo Judje navado pokopavati.',
        41: 'Bil je pa vrt v kraju, kjer je bil križan, in na vrtu nov grob, v katerega še nikoli nihče ni bil položen.',
        42: 'Tu torej, zavoljo judovskega dneva pripravljanja, ker je bil grob blizu, položita Jezusa.',
    },
    20: {
        1: 'A prvi dan tedna pride Marija Magdalena zgodaj, ko je še tema bilo, h grobu; in ugleda, da je kamen odvaljen od groba.',
        2: 'Tedaj zbeži in pride k Simonu Petru in k drugemu učencu, ki ga je Jezus ljubil, in jima reče: Vzeli so Gospoda iz groba, in ne vemo, kam so ga položili.',
        3: 'Peter torej gre ven in drugi učenec, in šla sta h grobu.',
        4: 'Tečeta pa oba skupaj; a drugi učenec teče hitreje nego Peter in pride prvi h grobu,',
        5: 'in sklonivši se, ugleda platnene povoje, da leže; toda ne vstopi.',
        6: 'Tedaj pride tudi Simon Peter za njim, stopi v grob in vidi povoje, da leže,',
        7: 'in potni prt, ki je bil na glavi njegovi, da ne leži z drugimi prti, temuč je posebe zvit na enem kraju.',
        8: 'Tedaj stopi noter tudi drugi učenec, ki je bil prvi prišel h grobu, in vidi to in veruje.',
        9: 'Nista še namreč umela pisma, da mora on iz mrtvih vstati.',
        10: 'In učenca zopet odideta k svojim.',
        11: 'Marija pa stoji zunaj pri grobu in joka. Ko pa joka, se skloni v grob',
        12: 'in ugleda dva angela v belih oblačilih, da sedita, eden pri glavi in drugi pri nogah, kjer je bilo ležalo truplo Jezusovo.',
        13: 'In ona ji rečeta: Žena, kaj jokaš? Reče jima: Ker so Gospoda mojega vzeli, in ne vem, kam so ga položili.',
        14: 'To rekši, se obrne in ugleda Jezusa, da tu stoji; pa ne ve, da je Jezus.',
        15: 'Reče ji Jezus: Žena, kaj jokaš? koga iščeš? Ona, misleč, da je vrtnar, mu reče: Gospod, če si ga ti odnesel, povej mi, kam si ga položil; in jaz ga bom vzela.',
        16: 'Reče ji Jezus: Marija! Ona se obrne in mu reče hebrejski: Rabuni! (kar se pravi: Učenik).',
        17: 'Veli ji Jezus: Ne dotikaj se me, ker še nisem šel gori k Očetu. Pojdi pa k bratom mojim in jim povej: Grem gori k svojemu Očetu in vašemu Očetu in svojemu Bogu in vašemu Bogu.',
        18: 'Marija Magdalena pride in oznani učencem, da je videla Gospoda in da ji je to rekel.',
        19: 'Ko je pa bil večer tistega dneva, prvega v tednu, in so bile duri zaklenjene, kjer so bili učenci zbrani, zavoljo strahu pred Judi, pride Jezus in stopi v sredo mednje in jim reče: Mir vam!',
        20: 'In ko je to rekel, jim pokaže roke in svojo stran. Razvesele se tedaj učenci, videč Gospoda.',
        21: 'Jezus jim torej zopet reče: Mir vam! Kakor je Oče mene poslal, tudi jaz pošiljam vas.',
        22: 'In ko je to rekel, dahne vanje, in jim veli: Prejmite svetega Duha.',
        23: 'Katerimkoli odpustite grehe, so jim odpuščeni, katerimkoli jih zadržite, so jim zadržani.',
        24: 'Tomaž pa, eden dvanajsterih, ki se imenuje Dvojček, ni bil ž njimi, ko je Jezus prišel.',
        25: 'Pravili so mu torej drugi učenci: Videli smo Gospoda. On jim pa reče: Ako ne vidim na rokah njegovih znamenj od žebljev in ne položim prsta svojega v rano od žebljev in ne denem roke svoje v stran njegovo: ne bom veroval.',
        26: 'In čez osem dni so zopet učenci njegovi notri, in Tomaž ž njimi. Jezus pride, ko so duri zaklenjene, in stopi v sredo mednje in reče: Mir vam!',
        27: 'Potem veli Tomažu: Položi prst svoj sem, in poglej roke moje; in podaj roko svojo in položi jo v stran mojo: in ne bodi neveren, ampak veren.',
        28: 'Tomaž odgovori in mu reče: Gospod moj in Bog moj!',
        29: 'Reče mu Jezus: Ker si me videl, Tomaž, veruješ; blagor jim, ki ne vidijo, pa verujejo.',
        30: 'In Jezus je storil pred učenci svojimi še veliko drugih znamenj, ki niso zapisana v tej knjigi.',
        31: 'A ta so zapisana, da verujete: Jezus je Kristus, Sin Božji, in da verujoč imate življenje v imenu njegovem.',
    },
    21: {
        1: 'Potem se je Jezus zopet razodel učencem pri morju Tiberijskem; razodel se je pa takole:',
        2: 'Bili so skupaj Simon Peter in Tomaž, ki se imenuje Dvojček, in Natanael iz Kane Galilejske in Zebedejeva sina in druga dva izmed učencev njegovih.',
        3: 'Reče jim Simon Peter: Ribe grem lovit. Reko mu: Tudi mi pojdemo s teboj. Ter gredo in vstopijo v ladjo, in tisto noč niso nič ujeli.',
        4: 'Ko pa že napoči jutro, stoji Jezus na bregu; ali učenci ne vedo, da je Jezus.',
        5: 'Jezus jim torej reče: Otroci, imate li kake jedi? Odgovore mu: Nimamo.',
        6: 'On jim pa reče: Vrzite mrežo na desno stran ladje, pa najdete. Vržejo torej, a sedaj je ne morejo izvleči zaradi množice rib.',
        7: 'Tedaj reče tisti učenec, ki ga je Jezus ljubil, Petru: Gospod je! Simon Peter torej, ko zasliši, da je Gospod, si opaše vrhnjo haljo (bil je namreč nag) in se spusti v morje.',
        8: 'A drugi učenci pridejo z ladjo (niso bili namreč daleč od kopnega, samo kakih dvesto komolcev) in vlečejo mrežo polno rib.',
        9: 'Ko pa izstopijo na kopno, ugledajo žerjavico pripravljeno in na njej ribo položeno in kruh.',
        10: 'Veli jim Jezus: Prinesite od rib, ki ste jih sedaj ujeli.',
        11: 'Simon Peter stopi torej v ladjo in izvleče mrežo na suho, polno velikih rib, sto in triinpetdeset; in dasi jih je bilo toliko, ni se mreža raztrgala.',
        12: 'Veli jim Jezus: Pridite, obedujte! Nobeden od učencev pa si ga ni upal vprašati: Kdo si ti? vedoč, da je Gospod.',
        13: 'Pride Jezus in vzame kruh in jim ga da, in tako tudi ribo.',
        14: 'S tem se je že v tretje razodel Jezus učencem, odkar je bil vstal iz mrtvih.',
        15: 'Ko so torej poobedovali, reče Jezus Simonu Petru: Simon Jonov, ljubiš li me bolj nego ti? Reče mu: Da, gospod, ti veš, da te ljubim. Veli mu: Pasi moja jagnjeta.',
        16: 'Reče mu zopet drugič: Simon Jonov, ali me ljubiš? Reče mu: Da, gospod, ti veš, da te ljubim. Veli mu: Pastiruj mojim ovcam.',
        17: 'Reče mu v tretje: Simon Jonov, ali me ljubiš? Peter se razžalosti, ker mu je tretjič rekel: Ali me ljubiš? in mu reče: Gospod, ti vse veš; ti znaš, da te ljubim. Veli mu Jezus: Pasi moje ovčice.',
        18: 'Resnično, resnično ti pravim: Ko si bil mlajši, si se opasoval sam in hodil, kamor si hotel; ko se pa postaraš, raztegneš roke svoje in drugi te opaše in te povleče, kamor ti nočeš.',
        19: 'To je pa povedal, da naznači, s kako smrtjo bo oslavil Boga. In ko je to povedal, mu veli: Pojdi za menoj.',
        20: 'Obrnivši se pa ugleda Peter učenca, ki ga je Jezus ljubil, da gre za njim, ki je bil tudi pri večerji slonel na prsih njegovih in je rekel: Gospod, kdo je tisti, ki te izda?',
        21: 'Ko torej Peter vidi tega, reče Jezusu: Gospod, kaj pa ta?',
        22: 'Reče mu Jezus: Ako hočem, da ostane dotlej, ko pridem, kaj tebi za to? Ti pojdi za menoj!',
        23: 'Razglasila se je torej med brati ta beseda: Ta učenec ne umrje. Toda Jezus mu ni rekel, da ne umrje, ampak: Ako hočem, da ostane dotlej, ko pridem, kaj tebi za to?',
        24: 'Ta učenec je tisti, ki pričuje o tem in je napisal to; in vemo, da je pričevanje njegovo resnično.',
        25: 'Je pa še veliko drugega, kar je storil Jezus; ko bi se to vse posamez napisalo, menim, da tudi ves svet ne bi imel prostora za knjige, ki bi se morale napisati.',
    },
}
